/* Spanish translation of the Certified Kubernetes Application Developer practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("ckad", {
  "ck1": ["Un desarrollador necesita ejecutar una migración de base de datos una sola vez, que Kubernetes la reintente si el contenedor falla y luego se detenga. ¿Qué recurso es el MÁS adecuado?", ["Deployment", "DaemonSet", "Job", "ReplicaSet"], "Un Job ejecuta Pods hasta que terminan con éxito y reintenta las fallas hasta backoffLimit. Un Deployment reiniciaría para siempre el contenedor terminado para mantener las réplicas en ejecución.", ["Un Deployment mantiene para siempre una cantidad fija de réplicas en ejecución, así que el contenedor de la migración terminado se reiniciaría una y otra vez.", "Un DaemonSet ejecuta un Pod de larga duración por nodo; no tiene el concepto de ejecutar una tarea una vez hasta completarla.", null, "Un ReplicaSet mantiene una cantidad fija de Pods en ejecución y los reinicia cuando terminan, así que nunca considera terminada una ejecución."]],
  "ck2": ["Un equipo debe ejecutar un agente de recolección de logs en cada nodo, incluidos los nodos que se agreguen después. ¿Qué recurso de carga de trabajo debe usar?", ["DaemonSet", "CronJob", "StatefulSet", "Deployment"], "Un DaemonSet programa un Pod por cada nodo elegible y agrega Pods automáticamente cuando se unen nodos. Un Deployment reparte las réplicas sin garantizar una por nodo.", [null, "Un CronJob ejecuta Jobs según un horario y esos Jobs terminan; no mantiene un agente en ejecución en cada nodo.", "Un StatefulSet da a las réplicas nombres y almacenamiento estables, pero las coloca donde elija el scheduler, no una por nodo.", "Un Deployment reparte una cantidad fija de réplicas entre los nodos sin garantizar una por nodo, y no crece cuando se agregan nodos."]],
  "ck3": ["Una base de datos en clúster necesita nombres de Pod estables (db-0, db-1) y su propio PersistentVolumeClaim por réplica. ¿Qué recurso ofrece ambas cosas?", ["Un Job con parallelism en 3", "Un Deployment con un PVC ReadWriteMany compartido", "Un DaemonSet con un volumen hostPath", "Un StatefulSet con volumeClaimTemplates"], "Los StatefulSets dan identidades ordinales y estables y crean un PVC por réplica a partir de volumeClaimTemplates. Las réplicas de un Deployment son intercambiables y compartirían un solo claim.", ["Un Job ejecuta Pods hasta completarlos; parallelism solo controla la concurrencia y no da nombres estables ni claims por réplica.", "Los Pods de un Deployment reciben sufijos de nombre aleatorios, y un solo claim RWX compartido es lo contrario de un PVC por réplica.", "Un DaemonSet ejecuta un Pod por nodo, y hostPath ata los datos al sistema de archivos de un nodo en lugar de dar a cada réplica su propio claim.", null]],
  "ck4": ["Un CronJob de reportes debe ejecutarse todos los días a las 02:30. ¿Qué schedule es correcto?", ["2 30 * * *", "30 2 * * *", "* * 2 30 *", "0 2,30 * * *"], "Los campos de cron son minuto, hora, día del mes, mes y día de la semana, así que 30 2 * * * es a las 02:30 todos los días. \"2 30 * * *\" pone 30 en el campo de la hora, lo cual no es válido.", ["Esto pone 2 en el campo del minuto y 30 en el campo de la hora, lo cual no es válido porque las horas solo van de 0 a 23.", null, "Esto pone minuto y hora en todos los valores y coloca 2 y 30 en los campos de día del mes y mes, lo cual es incorrecto, y 30 es un mes inválido.", "Esto se ejecuta en el minuto 0 de las horas 2 y 30; la hora 30 no es válida, y aun las 02:00 no son las 02:30."]],
  "ck5": ["Un CronJob a veces tarda más que su intervalo, y las ejecuciones superpuestas corrompen los datos. ¿Qué configuración impide que inicie una nueva ejecución mientras la anterior sigue activa?", ["concurrencyPolicy: Replace", "successfulJobsHistoryLimit: 0", "startingDeadlineSeconds: 0", "concurrencyPolicy: Forbid"], "Forbid omite la nueva ejecución si el Job anterior sigue en ejecución. Replace terminaría el Job en ejecución e iniciaría uno nuevo, lo que sigue siendo una ejecución interrumpida.", ["Replace cancela el Job en ejecución e inicia el nuevo, así que las ejecuciones se siguen interrumpiendo entre sí en lugar de impedirse.", "Esto solo controla cuántos Jobs exitosos terminados se conservan; no afecta si las ejecuciones se superponen.", "startingDeadlineSeconds limita qué tan tarde puede iniciar una ejecución perdida; no verifica si un Job anterior sigue activo.", null]],
  "ck6": ["Quieres probar ahora mismo un CronJob llamado nightly sin esperar su schedule. ¿Qué comando lo hace?", ["kubectl run nightly --restart=OnFailure", "kubectl rollout restart cronjob/nightly", "kubectl create job test-run --from=cronjob/nightly", "kubectl patch cronjob nightly -p '{\"spec\":{\"suspend\":false}}'"], "`kubectl create job <name> --from=cronjob/<cj>` crea de inmediato un Job a partir del jobTemplate del CronJob. Quitar la suspensión solo permite que ocurran las ejecuciones programadas futuras.", ["kubectl run crea un Pod independiente a partir de una imagen y no sabe nada del jobTemplate del CronJob.", "rollout restart funciona con Deployments, StatefulSets y DaemonSets; los CronJobs no tienen rollouts que reiniciar.", null, "Poner suspend en false solo vuelve a habilitar las ejecuciones programadas futuras; nada se ejecuta hasta la siguiente hora programada."]],
  "ck7": ["La spec de un Job tiene `completions: 6` y `parallelism: 2`. ¿Cómo se ejecuta?", ["Seis Pods inician a la vez y dos deben tener éxito", "Se ejecutan hasta dos Pods a la vez hasta que seis hayan tenido éxito", "Se ejecutan dos Pods en total, cada uno reintentado seis veces", "Seis Pods se ejecutan uno tras otro, cada uno repetido dos veces"], "completions es la cantidad de Pods exitosos requeridos y parallelism limita cuántos se ejecutan de forma concurrente. No es un conteo de reintentos; los reintentos los controla backoffLimit.", ["Parallelism 2 limita los Pods concurrentes, así que seis no pueden iniciar a la vez, y completions 6 significa que se requieren seis éxitos, no dos.", null, "Ninguno de los dos campos es un conteo de reintentos; los reintentos los controla backoffLimit, y se requieren seis Pods exitosos.", "Parallelism 2 permite dos Pods a la vez en lugar de uno tras otro estrictamente, y nada repite cada Pod dos veces."]],
  "ck8": ["La plantilla de Pod de un Job establece `restartPolicy: Always` y el API server la rechaza. ¿Por qué?", ["Los Jobs requieren restartPolicy Never u OnFailure", "Los Jobs requieren omitir el campo restartPolicy", "Always solo es válido para init containers en los Jobs", "restartPolicy debe establecerse en cada contenedor, no en el Pod"], "Los Pods de un Job deben terminar, así que solo se permiten Never u OnFailure. Always es el valor predeterminado para los Deployments, que mantienen los contenedores en ejecución.", [null, "Omitir restartPolicy lo deja en Always de forma predeterminada, lo que los Jobs rechazan, así que la plantilla de un Job debe establecer Never u OnFailure explícitamente.", "restartPolicy: Always en un init container define un sidecar nativo, lo que no cambia la regla a nivel de Pod de que los Pods de un Job no pueden usar Always.", "restartPolicy es un campo a nivel de Pod; el campo por contenedor solo existe para init containers que actúan como sidecars, y no es el motivo del rechazo."]],
  "ck9": ["Una imagen tiene `ENTRYPOINT [\"python\"]` y `CMD [\"app.py\"]`. El Pod establece `args: [\"worker.py\"]` y ningún command. ¿Qué se ejecuta?", ["python worker.py", "worker.py sin intérprete", "python app.py worker.py", "python app.py"], "args reemplaza a CMD mientras se conserva el ENTRYPOINT de la imagen, lo que da python worker.py. Establecer command en su lugar habría reemplazado el ENTRYPOINT.", [null, "args no toca el ENTRYPOINT, así que python sigue siendo el ejecutable y recibe worker.py.", "args reemplaza a CMD en lugar de agregarse a él, así que app.py se descarta.", "Esto es lo que se ejecuta sin ninguna sobrescritura; establecer args reemplaza el CMD app.py por worker.py."]],
  "ck10": ["La imagen de un servicio en Go pesa 900 MB porque contiene el compilador y el código fuente. ¿Cuál es la MEJOR forma de reducirla?", ["Agregar un .dockerignore que incluya el archivo go.mod", "Compactar capas encadenando cada instrucción RUN con &&", "Ejecutar el contenedor con un límite de memoria más bajo", "Usar un multi-stage build que copie solo el binario"], "Un multi-stage build compila en una etapa y copia solo el binario a una imagen de runtime pequeña. Encadenar comandos RUN elimina algunas capas, pero sigue incluyendo toda la cadena de herramientas.", ["go.mod es muy pequeño y se necesita para el build; ignorarlo rompe el build y no hace nada respecto de la cadena de herramientas en la imagen.", "Encadenar comandos RUN reduce un poco la cantidad de capas, pero el compilador y el código fuente siguen incluidos en la imagen final.", "Un límite de memoria controla el uso de recursos en tiempo de ejecución y no afecta el tamaño de la imagen en disco.", null]],
  "ck11": ["En el examen debes construir una imagen desde ./app con el tag myapp:2.0 y guardarla como /tmp/myapp.tar. ¿Qué comandos de docker (o podman) lo hacen?", ["docker create myapp:2.0 ./app, luego docker export myapp:2.0 > /tmp/myapp.tar", "docker build -t myapp:2.0 ./app, luego docker save -o /tmp/myapp.tar myapp:2.0", "docker build ./app --name myapp:2.0, luego docker push /tmp/myapp.tar", "docker commit ./app myapp:2.0, luego docker load -i /tmp/myapp.tar"], "build -t etiqueta la imagen y save -o escribe la imagen (con todas sus capas) en un tarball. export funciona con contenedores, no con imágenes, y load hace lo contrario de save.", ["docker create crea un contenedor, no una imagen a partir de un contexto de build, y docker export aplana el sistema de archivos de un contenedor en lugar de guardar una imagen etiquetada.", null, "docker build no tiene una opción --name para etiquetar (es -t), y docker push sube a un registro en lugar de escribir un archivo tar.", "docker commit toma una instantánea de un contenedor en ejecución, no de un directorio, y docker load lee un tar hacia el almacén de imágenes en lugar de escribir uno."]],
  "ck12": ["Un Pod debe esperar a que un Service de base de datos se resuelva en DNS antes de que inicie el contenedor de la app. ¿Qué diseño es el adecuado?", ["Un contenedor sidecar que haga un bucle infinito", "Un lifecycle hook postStart en el contenedor de la aplicación", "Un init container que haga un bucle hasta que nslookup tenga éxito", "Una readiness probe en el Service de la base de datos"], "Los init containers se ejecutan hasta completarse antes de que inicien los contenedores de la app, así que un bucle de verificación DNS ahí bloquea el arranque. postStart se ejecuta junto con el entrypoint y no lo retrasa.", ["Un sidecar se ejecuta junto al contenedor de la app, así que un bucle ahí no retrasa el inicio de la app.", "postStart se ejecuta de forma concurrente con el entrypoint del contenedor, así que la app puede iniciar antes de que DNS esté listo.", null, "Los Services no tienen probes; las probes pertenecen a los contenedores, y una readiness probe nunca impide que otro contenedor inicie."]],
  "ck13": ["En el Kubernetes actual, ¿cómo declaras un sidecar nativo que inicie antes que la app y siga ejecutándose durante toda la vida del Pod?", ["Agregarlo en containers con la label role: sidecar", "Agregarlo en initContainers con restartPolicy: Always", "Agregarlo en ephemeralContainers en la spec del Pod", "Establecer shareProcessNamespace: true en el Pod"], "Un sidecar nativo es un init container con su propio restartPolicy: Always, así que inicia primero y no se espera a que termine. Las labels no tienen ningún significado especial para el kubelet.", ["El kubelet ignora las labels al decidir el comportamiento de los contenedores, así que esto es solo un contenedor de app común sin orden de arranque.", null, "Los ephemeral containers son contenedores temporales de depuración que se agregan a un Pod en ejecución con kubectl debug, no parte del arranque normal.", "shareProcessNamespace permite que los contenedores vean los procesos de los demás; no hace que un contenedor inicie primero ni que actúe como sidecar."]],
  "ck14": ["Dos contenedores de un Pod deben compartir archivos temporales, y los datos pueden perderse cuando se elimina el Pod. ¿Qué tipo de volumen es el más sencillo?", ["hostPath", "persistentVolumeClaim", "configMap", "emptyDir"], "emptyDir se crea con el Pod, lo comparten sus contenedores y se elimina con él. hostPath ataría el Pod al sistema de archivos de un nodo sin ningún beneficio.", ["hostPath monta un directorio del nodo, lo que ata el Pod a ese nodo y deja datos atrás cuando el Pod ya no existe.", "Un PVC da almacenamiento duradero que sobrevive al Pod, lo que implica más configuración de la necesaria para archivos temporales desechables.", "Un volumen configMap se llena a partir de un ConfigMap y es de solo lectura, así que los contenedores no pueden usarlo para intercambiar archivos temporales.", null]],
  "ck15": ["Lee este fragmento: `volumes: [{name: cache, emptyDir: {medium: Memory, sizeLimit: 64Mi}}]`. ¿Qué es cierto sobre el volumen?", ["Está respaldado por tmpfs y cuenta para el uso de memoria", "Se guarda en el disco del nodo y sobrevive a los reinicios", "Es un PVC que solicita 64Mi a la StorageClass", "Se comparte entre todos los Pods del nodo"], "medium: Memory monta el emptyDir como tmpfs, así que su contenido usa RAM y cuenta contra la memoria del contenedor. Sigue siendo por Pod y efímero.", [null, "medium: Memory significa tmpfs en RAM, no el disco del nodo, y el contenido de un emptyDir se elimina cuando se elimina el Pod.", "emptyDir no es un claim y no involucra una StorageClass; sizeLimit solo limita cuánto puede contener el volumen.", "Un emptyDir pertenece a un Pod y solo lo comparten los contenedores de ese Pod, no otros Pods del nodo."]],
  "ck16": ["Un PVC con `accessModes: [ReadWriteOnce]` está vinculado. ¿Qué garantiza ReadWriteOnce?", ["Solo un Pod del clúster puede leerlo en todo momento", "Se puede escribir una vez y luego pasa a ser de solo lectura", "Se puede montar en lectura-escritura en un solo nodo", "Todos los nodos pueden montarlo en lectura-escritura a la vez"], "ReadWriteOnce significa lectura-escritura en un solo nodo; varios Pods de ese nodo pueden usarlo igualmente. ReadWriteOncePod es el modo que lo limita a un solo Pod.", ["RWO restringe el montaje a un nodo, no a un Pod, y no dice nada sobre todo el clúster; ReadWriteOncePod es el modo de un solo Pod.", "Los access modes describen cuántos nodos pueden montar un volumen; ninguno hace que los datos se escriban una vez y luego queden de solo lectura.", null, "Eso describe ReadWriteMany; ReadWriteOnce limita el montaje en lectura-escritura a un solo nodo."]],
  "ck17": ["Un Pod se queda en Pending y describe muestra \"pod has unbound immediate PersistentVolumeClaims\". El PVC indica storageClassName: fast, que no existe. ¿Qué lo soluciona?", ["Eliminar y volver a crear el Pod", "Agregar una readiness probe al Pod", "Cambiar el PVC para que use una StorageClass existente", "Agregar un nodeSelector para que el Pod caiga en un nodo de almacenamiento"], "Sin una StorageClass que coincida, nada aprovisiona un volumen, así que el claim se queda en Pending. storageClassName de un PVC no se puede editar en el lugar, así que hay que volver a crear el PVC con una clase válida; volver a crear solo el Pod no cambia nada.", ["El nuevo Pod haría referencia al mismo claim sin vincular y se quedaría en Pending, porque no existe una StorageClass que aprovisione un volumen.", "Las readiness probes solo importan después de que un contenedor se ejecuta; no pueden ayudar a un Pod que no se programa por un claim sin vincular.", null, "El problema es que no se aprovisiona ningún volumen para el claim, no la ubicación en un nodo; un nodeSelector no puede crear la StorageClass que falta."]],
  "ck18": ["En la spec de un Pod, un volumeMount usa `name: data`, pero la lista volumes solo contiene `name: app-data`. ¿Qué pasa?", ["La API rechaza el Pod por inválido", "El montaje usa un emptyDir en silencio", "El kubelet monta app-data porque es el único volumen", "El Pod inicia y la ruta de montaje queda vacía"], "El nombre de cada volumeMount debe coincidir con un volumen definido en el Pod, así que la validación falla cuando se crea el Pod. No se adivina ni se asume nada por defecto.", [null, "Kubernetes nunca crea un volumen predeterminado para un nombre de montaje sin coincidencia; el Pod se rechaza durante la validación.", "El kubelet no adivina qué volumen quisiste usar; los nombres deben coincidir exactamente o el API server rechaza la spec.", "El Pod nunca llega a crearse, porque el API server valida los nombres de los volumeMounts antes de guardar el Pod."]],
  "ck19": ["El Deployment web ejecuta el contenedor web con nginx:1.25. ¿Qué comando inicia una actualización rolling a nginx:1.27?", ["kubectl replace deployment web nginx:1.27", "kubectl rollout update deployment/web --image=nginx:1.27", "kubectl edit pod web --image=nginx:1.27", "kubectl set image deployment/web web=nginx:1.27"], "`kubectl set image deployment/<name> <container>=<image>` cambia la plantilla del Pod, lo que dispara un rollout. Editar un Pod no cambia el Deployment y se sobrescribe.", ["kubectl replace necesita un archivo de manifiesto completo con -f; no recibe como argumentos el nombre de un Deployment y una imagen.", "No existe el subcomando rollout update, y --image no es una opción de rollout.", "kubectl edit no tiene una opción --image, y cambiar un Pod no cambia la plantilla del Deployment, así que el ReplicaSet lo reemplazaría.", null]],
  "ck20": ["Después de un release defectuoso, necesitas que el Deployment api vuelva específicamente a la revisión 3. ¿Qué comando usas?", ["kubectl rollout history deployment/api --revision=3", "kubectl rollout undo deployment/api --to-revision=3", "kubectl rollout restart deployment/api --revision=3", "kubectl apply deployment/api --revision=3"], "rollout undo con --to-revision revierte la plantilla a esa revisión. history con --revision solo muestra sus detalles.", ["rollout history con --revision solo imprime los detalles de esa revisión; no revierte nada.", null, "rollout restart vuelve a crear los Pods con la plantilla actual y no tiene una opción --revision.", "kubectl apply necesita un archivo de manifiesto y no tiene una opción --revision para volver a una revisión anterior de un Deployment."]],
  "ck21": ["Un Deployment tiene 4 réplicas, `maxSurge: 1` y `maxUnavailable: 0`. ¿Cuál es la cantidad máxima de Pods durante un rollout?", ["3", "4", "8", "5"], "maxSurge permite un Pod por encima de los 4 deseados, y maxUnavailable 0 significa que no se elimina ninguno antes de que los reemplazos estén listos, así que el máximo es 5.", ["maxUnavailable 0 significa que la cantidad nunca baja de los 4 deseados, así que 3 es imposible durante el rollout.", "4 es la cantidad deseada; maxSurge 1 permite que el controlador cree un Pod extra por encima de ella.", "maxSurge 1 permite solo un Pod extra, no un segundo conjunto completo de 4.", null]],
  "ck22": ["Una app no puede ejecutar dos versiones al mismo tiempo por un bloqueo del esquema. La inactividad es aceptable. ¿Qué estrategia de Deployment es la adecuada?", ["RollingUpdate con maxSurge 25%", "RollingUpdate con maxUnavailable 0", "Recreate", "Un canary con una réplica"], "Recreate termina todos los Pods anteriores antes de crear los nuevos, así que las versiones nunca se superponen. Cualquier configuración de RollingUpdate ejecuta Pods viejos y nuevos juntos durante un tiempo.", ["Una actualización rolling con surge siempre ejecuta Pods viejos y nuevos lado a lado, lo que el bloqueo del esquema prohíbe.", "maxUnavailable 0 mantiene los Pods viejos en ejecución hasta que los nuevos están listos, así que las versiones se superponen durante todo el rollout.", null, "Un canary ejecuta deliberadamente la nueva versión junto a la anterior, que es justo lo que el bloqueo no permite."]],
  "ck23": ["Ejecutas los Deployments web-blue y web-green, con las labels version=blue y version=green. ¿Cómo pasas todo el tráfico a green de una sola vez?", ["Escalar web-blue a cero y luego esperar el rollout", "Apuntar el selector del Service a version=green", "Ejecutar kubectl rollout undo en web-blue", "Agregar version=green a la plantilla de Pod de web-blue"], "En blue/green, el selector del Service decide qué conjunto recibe el tráfico, y modificarlo cambia todo en un solo paso mientras blue sigue listo para un rollback. Escalar blue hacia abajo primero causa una ventana de interrupción.", ["Escalar blue a cero antes de cambiar el tráfico crea una ventana de interrupción y no es el cambio en un solo paso del que depende blue/green.", null, "rollout undo devuelve la plantilla de web-blue a una revisión anterior; no mueve el tráfico a web-green.", "Volver a etiquetar los Pods de blue como green haría que la versión anterior reciba el tráfico destinado a green, lo que anula el cambio."]],
  "ck24": ["El Service shop selecciona app=shop. El Deployment shop-v1 tiene 9 réplicas y shop-v2 tiene 1, ambos con la label app=shop. ¿Qué es esta configuración?", ["Un canary que envía alrededor del 10% del tráfico a v2", "Un despliegue blue/green", "Un rollout Recreate en curso", "Una actualización por partition de un StatefulSet"], "Ambas versiones coinciden con el selector del Service, así que el tráfico se reparte aproximadamente según la cantidad de Pods: 1 de 10. En blue/green, el Service seleccionaría una sola versión a la vez.", [null, "Blue/green apunta el Service a una versión a la vez; aquí ambas versiones coinciden con el selector y reciben tráfico juntas.", "Recreate termina todos los Pods anteriores antes de iniciar los nuevos, así que las dos versiones no estarían ejecutándose lado a lado.", "Son Deployments, no un StatefulSet, y las actualizaciones por partition solo aplican a las actualizaciones rolling de StatefulSets."]],
  "ck25": ["¿Qué cambio en un Deployment crea una nueva revisión de ReplicaSet?", ["Cambiar una variable de entorno en la plantilla del Pod", "Escalar las réplicas de 3 a 6", "Agregar una annotation en la sección metadata del propio Deployment", "Cambiar revisionHistoryLimit"], "Solo los cambios en spec.template disparan un rollout y un nuevo ReplicaSet. Escalar cambia la cantidad de réplicas del ReplicaSet existente.", [null, "Escalar solo cambia la cantidad de réplicas del ReplicaSet actual; la plantilla del Pod no cambia, así que no se crea una revisión nueva.", "Las annotations en la metadata del propio Deployment están fuera de spec.template y no disparan un rollout.", "revisionHistoryLimit controla cuántos ReplicaSets anteriores se conservan; cambiarlo no altera la plantilla del Pod."]],
  "ck26": ["Necesitas hacer varios cambios en un Deployment sin disparar un rollout después de cada uno. ¿Qué comandos ayudan?", ["kubectl scale --replicas=0 y luego volver a escalar", "kubectl annotate deployment --overwrite y luego kubectl rollout restart", "kubectl delete deployment y luego volver a aplicarlo", "kubectl rollout pause, aplicar los cambios y kubectl rollout resume"], "Pausar un rollout te permite agrupar los cambios en la plantilla; resume inicia un solo rollout con todos ellos. Escalar a cero causa inactividad.", ["Escalar a cero causa inactividad y no impide que cada cambio de la plantilla dispare su propio rollout.", "rollout restart dispara otro rollout de inmediato, lo contrario de agrupar cambios.", "Eliminar el Deployment deja la app completamente caída y descarta su historial de revisiones.", null]],
  "ck27": ["Quieres instalar el chart bitnami/nginx como un release llamado web en el namespace frontend, que todavía no existe. ¿Qué comando usas?", ["helm install bitnami/nginx web -n frontend", "helm install web bitnami/nginx -n frontend --create-namespace", "helm create web bitnami/nginx --namespace frontend --create-namespace", "helm upgrade bitnami/nginx --name web -n frontend"], "La sintaxis es helm install <release> <chart>, y --create-namespace crea el namespace. helm create, en cambio, genera la estructura de un chart local nuevo.", ["El orden de los argumentos es incorrecto: helm install recibe primero el nombre del release y después el chart, y el namespace faltante no se crea.", null, "helm create genera el directorio de un chart local nuevo; no instala un chart desde un repositorio.", "helm upgrade recibe <release> <chart> y no tiene opción --name en Helm 3; además necesita un release existente, a menos que se use --install."]],
  "ck28": ["Antes de instalar un chart, quieres ver qué configuraciones puedes sobrescribir. ¿Qué comando muestra sus valores predeterminados?", ["helm get values <chart>", "helm list --values", "helm show values <chart>", "helm status <chart>"], "helm show values imprime el values.yaml del chart. helm get values lee los valores de un release instalado, no de un chart.", ["helm get values lee los valores proporcionados por el usuario en un release instalado, no los predeterminados de un chart.", "helm list muestra los releases instalados y no tiene una opción --values para enumerar la configuración de un chart.", null, "helm status informa el estado de un release instalado, no los valores configurables de un chart."]],
  "ck29": ["El release api se actualizó a la revisión 4 y está fallando. ¿Qué comando lo devuelve a la revisión 3?", ["helm undo api --revision 3", "helm rollback api 3", "helm upgrade api --revision 3", "helm history api 3"], "helm rollback <release> <revision> vuelve a desplegar una revisión anterior, creando una nueva revisión 5. helm history solo enumera las revisiones.", ["No existe el comando helm undo; el rollback se hace con helm rollback.", null, "helm upgrade no tiene opción --revision; instala un chart o valores nuevos y siempre crea una revisión nueva.", "helm history enumera las revisiones de un release, pero no cambia nada."]],
  "ck30": ["Debes encontrar todos los releases de Helm del clúster, en todos los namespaces. ¿Qué comando usas?", ["helm search repo --all", "kubectl get helm -A", "helm status --all", "helm list -A"], "helm list -A (--all-namespaces) enumera los releases de todas partes. helm search busca charts en repositorios, no releases instalados.", ["helm search repo busca charts en los repositorios configurados, no releases instalados en el clúster.", "Los releases de Helm no son un tipo de recurso de Kubernetes que kubectl get pueda enumerar de forma predeterminada.", "helm status informa sobre un release con nombre y no tiene una opción --all para enumerar todos los releases.", null]],
  "ck31": ["Quieres renderizar localmente los manifiestos de un chart con tu archivo de valores sin instalar nada. ¿Qué comando usas?", ["helm template myrel ./chart -f values.yaml", "helm install --dry-run=false", "helm package ./chart -f values.yaml", "helm pull ./chart --render"], "helm template renderiza las plantillas a YAML en tu máquina. helm package solo construye un archivo .tgz del chart.", [null, "--dry-run=false solo hace una instalación normal, justo lo que querías evitar, y no se indica ni el nombre del release ni el chart.", "helm package empaqueta el directorio de un chart en un archivo .tgz; no renderiza plantillas con valores.", "helm pull descarga un chart desde un repositorio y no tiene una opción --render."]],
  "ck32": ["Un directorio contiene un kustomization.yaml que enumera deployment.yaml y service.yaml. ¿Qué comando aplica el resultado personalizado?", ["kubectl apply -f kustomization.yaml", "kubectl create -r ./overlay", "kubectl apply -k ./overlay", "kubectl kustomize apply ./overlay"], "-k le indica a kubectl que construya la kustomization de ese directorio y aplique el resultado. Aplicar kustomization.yaml con -f enviaría el propio archivo Kustomization, que no es un recurso del clúster.", ["Con -f, kubectl envía el propio archivo Kustomization, que no es un recurso que acepte el API server, en lugar de construir el overlay.", "kubectl create -r no es una forma válida de construir una kustomization; -R es la opción recursiva de -f, y no hay paso de construcción.", null, "kubectl kustomize solo construye e imprime YAML; no tiene un subcomando apply."]],
  "ck33": ["En un overlay de Kustomize quieres que el nombre de cada recurso empiece con prod- y que cada imagen nginx use el tag 1.27. ¿Qué campos lo hacen?", ["commonAnnotations y replicas", "nameSuffix y patches", "namePrefix e images", "generatorOptions e images"], "namePrefix antepone texto a los nombres de los recursos e images sobrescribe los nombres o tags de las imágenes. nameSuffix agrega al final en lugar de anteponer.", ["commonAnnotations agrega annotations y replicas cambia la cantidad de réplicas; ninguno renombra recursos ni cambia tags de imágenes.", "nameSuffix agrega al final de los nombres en lugar de anteponer, y patches es una forma más pesada de cambiar imágenes que el campo images.", null, "generatorOptions afecta a los generadores de ConfigMaps y Secrets, como los sufijos de hash, y no renombra recursos."]],
  "ck34": ["Quieres revisar qué va a producir un overlay antes de aplicarlo. ¿Qué comando imprime el YAML renderizado?", ["kubectl kustomize ./overlay", "kubectl diff -f ./overlay", "kubectl get -k ./overlay", "kubectl explain -k ./overlay"], "kubectl kustomize <dir> construye e imprime el resultado sin contactar a la API para hacer cambios. kubectl diff compara contra el clúster y necesita -k para leer una kustomization.", [null, "kubectl diff compara contra el clúster en vivo en lugar de solo imprimir YAML, y con -f no construiría la kustomization.", "kubectl get -k vuelve a leer los objetos indicados desde el clúster; no imprime el overlay renderizado localmente.", "kubectl explain muestra la documentación de los campos de los tipos de recursos y no acepta un directorio de kustomization."]],
  "ck35": ["Después de `kubectl apply` quieres esperar hasta que el rollout de un Deployment termine o falle. ¿Qué comando usas?", ["kubectl rollout history deployment/web", "kubectl get deployment web --watch-only", "kubectl wait pod --for=complete", "kubectl rollout status deployment/web"], "rollout status se bloquea hasta que el rollout se completa o supera su progress deadline. rollout history solo muestra las revisiones pasadas.", ["rollout history enumera las revisiones pasadas y regresa de inmediato en lugar de esperar el rollout actual.", "--watch-only transmite los cambios del objeto Deployment, pero nunca termina ante el éxito o la falla, así que no es una espera adecuada.", "Los Pods de un Deployment nunca quedan complete, y kubectl wait además necesita un destino; esto no sigue el rollout.", null]],
  "ck36": ["Intentas cambiar `spec.selector.matchLabels` en un Deployment apps/v1 existente y la API lo rechaza. ¿Por qué?", ["Los selectores solo se pueden cambiar con kubectl edit, no con kubectl apply", "El selector de un Deployment apps/v1 es inmutable", "Primero hay que cambiar las labels en el ReplicaSet", "Los selectores no pueden contener más de una label"], "En apps/v1, el selector de un Deployment no se puede cambiar después de crearlo, así que debes crear un Deployment nuevo. La herramienta de edición no hace ninguna diferencia.", ["La regla la aplica el API server, así que kubectl edit se rechaza exactamente igual que kubectl apply.", null, "No se puede resolver editando los ReplicaSets; el controlador del Deployment es su dueño y el selector del Deployment sigue siendo inmutable.", "Los selectores pueden coincidir con varias labels; la cantidad de labels no tiene nada que ver con este rechazo."]],
  "ck37": ["Un manifiesto antiguo usa `apiVersion: extensions/v1beta1` para un Ingress y falla en un clúster actual. ¿Qué debe usar?", ["networking.k8s.io/v1beta1", "ingress.k8s.io/v1", "apps/v1", "networking.k8s.io/v1"], "Ingress pasó a networking.k8s.io/v1 y las versiones beta se eliminaron en 1.22. networking.k8s.io/v1beta1 es una de esas versiones eliminadas.", ["networking.k8s.io/v1beta1 para Ingress también se eliminó en 1.22, así que el manifiesto seguiría fallando.", "ingress.k8s.io no es un grupo de API real; Ingress vive en networking.k8s.io.", "apps/v1 sirve Deployments, StatefulSets, DaemonSets y ReplicaSets, no Ingress.", null]],
  "ck38": ["¿Qué comando muestra cada tipo de recurso con su grupo/versión de API y su nombre corto en el clúster actual?", ["kubectl cluster-info", "kubectl version", "kubectl api-resources", "kubectl config view"], "api-resources enumera cada tipo servido con su grupo/versión, nombre corto y si pertenece a un namespace. kubectl version solo informa las versiones del cliente y del servidor.", ["cluster-info imprime las direcciones del control plane y de los servicios principales, no una lista de tipos de recursos.", "kubectl version solo informa las versiones del cliente y del servidor.", null, "config view muestra los clústeres, usuarios y contextos del kubeconfig, no los recursos de API que ofrece el servidor."]],
  "ck39": ["Un manifiesto de CronJob usa `apiVersion: batch/v1beta1` y se rechaza. ¿Cuál debe ser el apiVersion?", ["batch/v2", "batch/v1", "apps/v1", "cronjob/v1"], "CronJob es estable en batch/v1, y batch/v1beta1 se eliminó en Kubernetes 1.25. No existe batch/v2.", ["No existe la versión de API batch/v2; CronJob solo se sirve en batch/v1.", null, "apps/v1 sirve controladores de cargas de trabajo como los Deployments, no CronJobs, que están en el grupo batch.", "cronjob/v1 no es un grupo de API; apiVersion lleva el grupo (batch) y la versión (v1)."]],
  "ck40": ["La readiness probe de un Pod empieza a fallar mientras su liveness probe sigue pasando. ¿Qué pasa?", ["El Pod se quita de los endpoints del Service", "El kubelet reinicia el contenedor", "El Pod se desaloja hacia otro nodo", "El Deployment hace rollback automáticamente a la revisión anterior"], "Una falla de readiness solo detiene el tráfico al quitar el Pod de los endpoints. Reiniciar el contenedor es lo que hace una falla de liveness.", [null, "Los reinicios los dispara una liveness probe que falla; las fallas de readiness nunca reinician el contenedor.", "Las probes nunca desalojan ni reprograman Pods; el desalojo viene de la presión en el nodo o de la preemption.", "Los Deployments no hacen rollback automáticamente por fallas de probes; un rollback requiere kubectl rollout undo."]],
  "ck41": ["Una app Java tarda hasta 3 minutos en iniciar, y su liveness probe la termina durante el arranque. ¿Cuál es la MEJOR solución?", ["Agregar una startupProbe que cubra el tiempo de arranque", "Eliminar por completo la liveness probe", "Establecer el timeoutSeconds de la liveness probe en 180 segundos", "Cambiar restartPolicy a Never"], "Una startupProbe suspende las verificaciones de liveness y readiness hasta que tiene éxito, lo que protege los arranques lentos y conserva la detección de bloqueos después. Un timeout de 180 segundos haría extremadamente lenta cada verificación posterior.", [null, "Quitar la liveness detiene las terminaciones durante el arranque, pero también pierde la recuperación automática ante bloqueos una vez que la app está en ejecución.", "timeoutSeconds es cuánto espera una verificación una respuesta, así que 180 segundos haría muy lenta cada verificación posterior en lugar de cubrir el arranque.", "restartPolicy Never no está permitido para los Pods de un Deployment, y detendría toda recuperación en lugar de proteger el periodo de arranque."]],
  "ck42": ["Lee esta probe: `livenessProbe: {httpGet: {path: /healthz, port: 8080}, periodSeconds: 10, failureThreshold: 3}`. ¿Cuándo se reinicia el contenedor?", ["Después de una verificación fallida", "Solo si /healthz devuelve un código 5xx tres veces en un minuto", "Después de 10 verificaciones fallidas", "Después de tres verificaciones fallidas seguidas, unos 30 segundos"], "El kubelet verifica cada 10 segundos y reinicia después de 3 fallas consecutivas. Cualquier estado fuera de 200–399, o la falta de respuesta, cuenta como falla.", ["failureThreshold 3 significa que se tolera una falla; el kubelet espera tres fallas consecutivas.", "Cuenta cualquier estado fuera de 200-399 o un timeout, no solo los 5xx, y las fallas deben ser consecutivas en lugar de ocurrir dentro de un minuto.", "El umbral es de 3 fallas consecutivas, no 10; 10 es el valor de periodSeconds.", null]],
  "ck43": ["Un contenedor no tiene endpoint HTTP, pero acepta conexiones TCP en el puerto 5432. ¿Qué handler de probe es el MÁS apropiado?", ["httpGet en el puerto 5432", "tcpSocket en el puerto 5432", "exec ejecutando curl localhost:5432", "grpc en el puerto 5432"], "tcpSocket tiene éxito si se puede abrir una conexión TCP, lo que sirve para el puerto de una base de datos. httpGet fallaría porque el servidor no habla HTTP.", ["httpGet envía una solicitud HTTP, que un servidor no HTTP como PostgreSQL no puede responder correctamente, así que la probe fallaría.", null, "curl habla HTTP, así que contra un puerto no HTTP da error, y es posible que la imagen ni siquiera incluya curl.", "Una probe grpc necesita que la app implemente el protocolo de health checking de gRPC, cosa que un servicio TCP simple no hace."]],
  "ck44": ["El contenedor app del Pod api se reinicia una y otra vez. ¿Qué comando muestra la salida de la instancia anterior que se cayó?", ["kubectl describe logs api -c app", "kubectl logs api --since=prev", "kubectl logs api -c app --previous", "kubectl get logs api app -p=false"], "--previous (-p) devuelve los logs de la última instancia terminada del contenedor. Los logs actuales pueden estar vacíos justo después de un reinicio.", ["describe no tiene un subcomando logs; muestra los detalles y eventos de un objeto, no la salida del contenedor.", "--since recibe una duración como 5m, no prev, y filtra los logs actuales en lugar de devolver la salida de la instancia caída.", null, "No existe el recurso kubectl get logs, y -p=false pediría explícitamente el contenedor actual, no el anterior."]],
  "ck45": ["Quieres logs en vivo de todos los Pods con la label app=web, en todos sus contenedores. ¿Qué comando funciona?", ["kubectl logs deployment -A app=web", "kubectl logs -l app=web --all-containers -f", "kubectl get logs --selector app=web", "kubectl describe pods -l app=web --follow"], "-l selecciona los Pods por label, --all-containers incluye cada contenedor y -f sigue la salida. describe muestra eventos, no streams de logs.", ["kubectl logs recibe un solo recurso y una label con -l, no app=web como argumento posicional, y -A no se usa aquí.", null, "Los logs no son un recurso de la API, así que kubectl get logs no existe.", "describe muestra los detalles y eventos de los Pods, no streams de logs, y no tiene una opción --follow."]],
  "ck46": ["`kubectl top pod` devuelve \"Metrics API not available\". ¿Qué falta?", ["El --read-only-port del kubelet", "kube-state-metrics en kube-system", "Un CRD de Prometheus Operator", "metrics-server ejecutándose en el clúster"], "kubectl top lee la API metrics.k8s.io, que proporciona metrics-server. kube-state-metrics expone el estado de los objetos para Prometheus, no la Metrics API.", ["El read-only port es un endpoint heredado del kubelet; habilitarlo no proporciona la API metrics.k8s.io que necesita kubectl top.", "kube-state-metrics expone el estado de los objetos para que Prometheus lo recolecte, no la Metrics API de recursos que lee kubectl top.", "Los CRDs de Prometheus Operator administran despliegues de Prometheus; no sirven metrics.k8s.io.", null]],
  "ck47": ["Un Pod muestra el estado ImagePullBackOff. ¿Cuál es la causa MÁS probable?", ["Nombre o tag de imagen incorrecto, o faltan credenciales del registro", "El contenedor superó su límite de memoria", "La ruta de la readiness probe devuelve 404", "El nodo tiene muy poca CPU y memoria libre para programar el Pod"], "ImagePullBackOff significa que el kubelet no pudo descargar la imagen: nombre o tag incorrecto, registro privado sin imagePullSecrets o problemas de red. Un problema de memoria se muestra como OOMKilled.", [null, "Superar un límite de memoria se muestra como OOMKilled después de que el contenedor inició, lo que requiere que la imagen ya se haya descargado.", "Una readiness probe que falla deja un contenedor en ejecución sin estar Ready; no tiene nada que ver con descargar la imagen.", "La falta de capacidad en los nodos deja el Pod en Pending con FailedScheduling, antes de intentar descargar cualquier imagen."]],
  "ck48": ["El último estado de un contenedor muestra `Reason: OOMKilled, Exit Code: 137`. ¿Qué significa esto?", ["La liveness probe falló tres veces seguidas y agotó el tiempo", "El nodo se quedó sin espacio en disco", "El contenedor superó su límite de memoria y fue terminado", "No se encontró el entrypoint de la imagen"], "OOMKilled significa que el uso de memoria superó el límite; 137 es 128 más SIGKILL (9). Un entrypoint faltante da un error de inicio, normalmente con código de salida 127 o 128.", ["Una falla de liveness reinicia el contenedor con un evento relacionado con la probe, no con el motivo OOMKilled.", "La presión de disco en el nodo lleva a un desalojo con un motivo como Evicted, no a OOMKilled con código de salida 137.", null, "Un entrypoint faltante produce un error de inicio, como el código de salida 127 o un mensaje ContainerCannotRun, no OOMKilled."]],
  "ck49": ["Un contenedor distroless no tiene shell, así que kubectl exec falla. ¿Cómo puedes inspeccionar sus procesos y su red?", ["kubectl attach --image=busybox", "kubectl cp busybox <pod>:/bin/sh", "kubectl debug -it <pod> --image=busybox --target=<container>", "kubectl run --overrides con hostPID"], "kubectl debug agrega un ephemeral container con herramientas; --target comparte el namespace de procesos del contenedor de destino. Copiar un binario de shell en una imagen distroless no es confiable y modifica el contenedor.", ["kubectl attach se conecta al stdio del proceso existente y no tiene una opción --image para traer herramientas.", "kubectl cp depende de tar dentro del contenedor, que una imagen distroless no tiene, y copiar binarios modifica el contenedor.", null, "kubectl run crea un Pod separado; incluso con hostPID no se une limpiamente al namespace de red del Pod de destino ni al namespace de procesos del contenedor."]],
  "ck50": ["Necesitas enumerar los eventos de un namespace en el orden en que ocurrieron. ¿Qué comando usas?", ["kubectl get events --sort-by=.metadata.creationTimestamp", "kubectl describe events --order=time", "kubectl logs events -n <ns>", "kubectl get events -o wide --watch-only=false"], "--sort-by con un JSONPath hacia creationTimestamp ordena los eventos por tiempo. describe no tiene una opción de orden, y los eventos no son logs.", [null, "kubectl describe no tiene una opción --order, y describir eventos no los enumera ordenados por tiempo.", "Los eventos son objetos de la API, no logs de contenedores, así que kubectl logs no puede leerlos.", "-o wide agrega columnas pero no ordena, y --watch-only=false solo desactiva un watch; la salida sigue sin estar ordenada por tiempo."]],
  "ck51": ["Un proveedor instaló un Operator, y necesitas ver qué nuevos tipos de recursos agregó. ¿Qué comando es el más rápido?", ["kubectl get apiservices -o yaml", "kubectl get operators --all", "kubectl describe nodes", "kubectl get crd"], "Las CustomResourceDefinitions registran tipos nuevos, así que enumerar los CRDs muestra lo que agregó el Operator. No existe un recurso operators integrado, a menos que otro CRD lo defina.", ["Los objetos APIService registran API servers agregados, y la mayoría de los Operators agregan tipos mediante CRDs, no mediante APIServices.", "No existe un recurso operators integrado; solo existiría si algún CRD (como el de OLM) lo definiera.", "describe nodes muestra la capacidad, las condiciones y los Pods de los nodos, no qué tipos de recursos existen.", null]],
  "ck52": ["¿Qué describe MEJOR a un Operator en Kubernetes?", ["Un rol de administrador del clúster con derechos RBAC completos sobre todos los namespaces", "Un controlador que administra una app mediante custom resources", "Un mutating webhook que inyecta sidecars", "Un Helm chart para instalar CRDs"], "Un Operator es un controlador personalizado que vigila custom resources y reconcilia la aplicación hacia el estado declarado. Un Helm chart puede instalar uno, pero no es en sí mismo un controlador.", ["Un Operator es software, no un rol de RBAC; necesita permisos RBAC, pero no es en sí mismo un conjunto de permisos.", null, "Un mutating webhook cambia los objetos al momento de la admisión; no reconcilia de forma continua el estado de una aplicación.", "Un Helm chart es un formato de empaquetado que puede instalar un Operator, pero no es un controlador que se ejecute en el clúster."]],
  "ck53": ["¿En qué orden procesa el API server una solicitud para crear un Pod?", ["Autorización, autenticación, admisión", "Admisión, autenticación, autorización", "Autenticación, admisión, autorización", "Autenticación, autorización, admisión"], "El servidor primero identifica a quien llama, luego verifica los permisos con RBAC y después ejecuta los admission controllers antes de guardar el objeto. La admisión solo puede actuar sobre solicitudes que ya se permitieron.", ["El servidor no puede verificar permisos antes de saber quién llama, así que la autenticación debe ir primero.", "La admisión se ejecuta al final sobre solicitudes ya autenticadas y autorizadas, no al principio.", "La autorización debe ocurrir antes de la admisión; los admission controllers solo ven solicitudes que RBAC ya permitió.", null]],
  "ck54": ["Un Pod se rechaza con un mensaje de ResourceQuota aunque RBAC permite que el usuario cree Pods. ¿Qué etapa lo rechazó?", ["Autenticación", "Autorización", "Admission control", "El scheduler"], "ResourceQuota lo aplica un admission controller después de que la autorización tiene éxito. El scheduler nunca ve un Pod rechazado.", ["La autenticación tuvo éxito porque se identificó al usuario; el error viene de una verificación de cuota, no de la identidad.", "RBAC permitió la creación, así que la autorización pasó; ResourceQuota no es una decisión de RBAC.", null, "El scheduler solo ve los Pods que se guardaron; un rechazo por cuota ocurre antes de que exista el objeto Pod."]],
  "ck55": ["Necesitas que el ServiceAccount app del namespace dev solo pueda hacer get, list y watch de Pods en dev. ¿Qué par de objetos es el adecuado?", ["ClusterRole y ClusterRoleBinding", "Role y RoleBinding en dev", "Role en dev y ClusterRoleBinding", "ClusterRoleBinding al ClusterRole view"], "Un Role y un RoleBinding otorgan permisos con alcance de namespace solo en dev. Un ClusterRoleBinding otorgaría acceso en todos los namespaces.", ["Un ClusterRoleBinding otorga los permisos en todos los namespaces, lo cual es más amplio que solo dev.", null, "Un ClusterRoleBinding no puede hacer referencia a un Role; solo puede vincular un ClusterRole, a nivel de todo el clúster.", "Vincular el ClusterRole view a nivel de clúster otorga acceso de lectura a muchos recursos en todos los namespaces, mucho más que los Pods de dev."]],
  "ck56": ["¿Qué comando verifica si el ServiceAccount app del namespace dev puede listar Secrets ahí?", ["kubectl auth can-i list secrets -n dev --as=system:serviceaccount:dev:app", "kubectl auth whoami --sa app -n dev", "kubectl get rolebinding app --can-i=secrets", "kubectl describe sa app --permissions"], "auth can-i con --as suplanta al ServiceAccount usando su nombre de usuario completo. auth whoami solo informa tu propia identidad.", [null, "auth whoami solo informa tu propia identidad y no tiene una opción --sa para probar los permisos de otro sujeto.", "kubectl get no tiene una opción --can-i; la salida de un RoleBinding no evalúa si una acción está permitida.", "describe sa muestra los tokens y secrets del ServiceAccount, y no existe una opción --permissions."]],
  "ck57": ["¿Qué comando crea un Role llamado pod-reader con get, list y watch sobre Pods?", ["kubectl create role pod-reader --verb=get,list,watch --resource=pods", "kubectl create rolebinding pod-reader --verb=get --resource=pods", "kubectl create clusterrole pod-reader --role=get,list,watch", "kubectl apply role pod-reader --pods=read"], "create role recibe --verb y --resource. Un RoleBinding vincula un Role con sujetos y no define verbos por sí mismo.", [null, "Un RoleBinding vincula sujetos con un Role; no acepta --verb ni --resource para definir permisos.", "--role no es una opción de create clusterrole, y un ClusterRole tiene alcance de clúster en lugar de ser el Role con namespace que se pidió.", "kubectl apply recibe manifiestos con -f, y no existe un atajo --pods=read para los permisos."]],
  "ck58": ["Un contenedor tiene `requests.memory: 256Mi` y `limits.memory: 512Mi`. Crece hasta 600Mi. ¿Qué pasa?", ["El kubelet lo limita de vuelta a 512Mi", "Nada, porque solo se aplican los requests", "El scheduler lo mueve a un nodo más grande", "Se termina por OOMKilled y se reinicia"], "La memoria no se puede limitar por throttling, así que superar el límite hace que el contenedor termine por OOMKilled. El throttling aplica a los límites de CPU.", ["La memoria no es comprimible, así que el kubelet no puede aplicarle throttling; solo los límites de CPU se aplican mediante throttling.", "Los limits los aplica en tiempo de ejecución el cgroup del kernel; los requests solo afectan la programación.", "El scheduler nunca mueve Pods en ejecución; la ubicación se decide una vez, y superar un límite lleva a una terminación, no a un traslado.", null]],
  "ck59": ["Un contenedor tiene `limits.cpu: 500m` e intenta usar dos núcleos completos. ¿Qué pasa?", ["Se termina con el código de salida 137", "Se limita por throttling a aproximadamente medio núcleo", "El Pod se desaloja de inmediato", "Se permite porque la CPU es comprimible"], "500m es 0.5 CPU y la cuota de CFS limita el uso a ese valor. La terminación ocurre con la memoria, no con la CPU.", ["La terminación con 137 ocurre al superar un límite de memoria; el uso excesivo de CPU se limita por throttling.", null, "El desalojo viene de la presión en el nodo, como falta de memoria o disco, no de que un contenedor alcance su propio límite de CPU.", "Que la CPU sea comprimible es la razón por la que se limita por throttling en lugar de terminarse, pero el límite se sigue aplicando, así que no se permiten dos núcleos."]],
  "ck60": ["Cada contenedor de un Pod establece requests de CPU y memoria iguales a sus limits. ¿Qué clase de QoS recibe el Pod?", ["BestEffort", "Burstable", "Guaranteed", "Critical"], "Requests iguales a los limits de CPU y memoria en todos los contenedores da Guaranteed. Burstable aplica cuando se establecen algunos requests, pero no coinciden con los limits.", ["BestEffort es para los Pods en los que ningún contenedor establece requests ni limits.", "Burstable aplica cuando se establece al menos un request o limit pero no todos coinciden; aquí coinciden exactamente.", null, "Critical no es una clase de QoS; las tres clases son Guaranteed, Burstable y BestEffort."]],
  "ck61": ["El namespace team-a tiene una ResourceQuota sobre requests.cpu. Un Pod sin CPU requests se rechaza. ¿Qué lo evita sin editar cada manifiesto?", ["Una PriorityClass con un valor alto", "Un LimitRange con requests predeterminados", "Un HorizontalPodAutoscaler", "Un PodDisruptionBudget"], "Un LimitRange inyecta requests y limits predeterminados en los contenedores que no los tienen, lo que satisface la cuota. Una PriorityClass afecta el orden de programación, no las cuotas.", ["Una PriorityClass afecta el orden de programación y la preemption; no agrega requests, así que la cuota sigue rechazando el Pod.", null, "Un HPA cambia la cantidad de réplicas según métricas y no puede agregar requests faltantes a la spec de un Pod.", "Un PodDisruptionBudget limita los desalojos voluntarios; no afecta la admisión por cuota."]],
  "ck62": ["¿Qué comando crea un ConfigMap llamado app-cfg con la key MODE=prod y el contenido de app.properties?", ["kubectl apply configmap app-cfg MODE=prod app.properties", "kubectl create secret generic app-cfg --from-literal=MODE=prod --from-file=app.properties", "kubectl create configmap app-cfg --env=MODE=prod --file app.properties", "kubectl create configmap app-cfg --from-literal=MODE=prod --from-file=app.properties"], "--from-literal agrega pares key=value y --from-file agrega una key con el nombre del archivo. create secret crearía un Secret, no un ConfigMap.", ["kubectl apply necesita un manifiesto con -f y no puede construir un ConfigMap a partir de argumentos posicionales key=value y de archivo.", "Esto crea un Secret, no un ConfigMap, aunque las opciones sean correctas.", "create configmap no tiene las opciones --env ni --file; las opciones son --from-literal, --from-file y --from-env-file.", null]],
  "ck63": ["Un Pod debe cargar cada key del ConfigMap app-cfg como variable de entorno. ¿Qué campo lo hace con la menor cantidad de YAML?", ["envFrom con configMapRef: {name: app-cfg}", "env con valueFrom.configMapKeyRef para cada key", "volumes con configMap: {name: app-cfg}", "spec.configMapName: app-cfg"], "envFrom importa todas las keys de una vez. configMapKeyRef funciona, pero necesita una entrada por key, y un volumen crea archivos, no variables de entorno.", [null, "configMapKeyRef funciona, pero necesita una entrada env separada por cada key, lo que es más YAML que envFrom.", "Un volumen configMap expone las keys como archivos en un directorio, no como variables de entorno.", "No existe un campo spec.configMapName en la spec de un Pod, así que la API lo rechazaría o lo ignoraría."]],
  "ck64": ["Un ConfigMap se usa tanto como variables de entorno como volumen montado (sin subPath). Actualizas el ConfigMap. ¿Qué cambia en los Pods en ejecución?", ["Ambos se actualizan en segundos", "Las variables de entorno se actualizan de inmediato; los archivos montados siguen igual", "Los archivos montados se actualizan con el tiempo; las variables de entorno no", "Nada se actualiza hasta que se reinicia el nodo"], "El kubelet refresca los volúmenes ConfigMap proyectados, pero las variables de entorno se leen solo al iniciar el contenedor. Las variables de entorno cambian solo después de reiniciar el Pod.", ["Las variables de entorno se leen solo cuando inicia el contenedor, así que no cambian en un Pod en ejecución.", "Es al revés: las variables de entorno quedan fijas hasta el reinicio, mientras que el kubelet refresca los archivos montados.", null, "No se necesita reiniciar el nodo; los archivos montados se refrescan después del periodo de sincronización del kubelet, y las variables de entorno se actualizan después de reiniciar el Pod."]],
  "ck65": ["Un compañero dice que los Secrets de Kubernetes son seguros porque sus valores se ven codificados en el YAML. ¿Qué es correcto?", ["kubectl cifra los valores con AES en tu máquina antes de subirlos", "Los valores se procesan con un hash y no se pueden volver a leer", "Los valores solo están codificados en base64, a menos que se configure el cifrado en reposo", "Los valores se guardan solo en la memoria de los nodos"], "base64 es una codificación que cualquiera puede revertir; la protección viene de RBAC y del cifrado en reposo del API server. Los Secrets se pueden volver a leer, así que no se procesan con hash.", ["kubectl no cifra los valores de los Secrets del lado del cliente; el campo data es solo texto en base64.", "Los valores de los Secrets deben ser legibles por los Pods que los usan, así que se codifican, no se procesan con hash.", null, "Los Secrets se guardan en etcd como los demás objetos; solo se mantienen en tmpfs en los nodos cuando se montan en Pods."]],
  "ck66": ["¿Qué comando crea un Secret llamado db-cred con password=S3cret?", ["kubectl create secret generic db-cred --from-literal=password=S3cret", "kubectl create secret tls db-cred --from-literal=password=S3cret", "kubectl create configmap db-cred --secret password=S3cret", "kubectl create secret db-cred password=S3cret --type=opaque"], "generic es el subcomando para Secrets Opaque a partir de literales o archivos. El tipo tls necesita los archivos --cert y --key.", [null, "El tipo tls requiere los archivos --cert y --key y no acepta --from-literal.", "Esto crearía un ConfigMap, y create configmap no tiene una opción --secret.", "create secret necesita un subtipo como generic, y los valores se pasan con --from-literal, no como argumentos posicionales."]],
  "ck67": ["Lee este fragmento: `env: [{name: DB_PASS, valueFrom: {secretKeyRef: {name: db-cred, key: pwd}}}]`. El Secret solo tiene una key llamada password. ¿Qué pasa?", ["DB_PASS se establece como una cadena vacía", "El Pod inicia e ignora DB_PASS", "Kubernetes usa la primera key que encuentre en el Secret", "El contenedor no logra iniciar por un error de configuración"], "Un secretKeyRef a una key inexistente causa CreateContainerConfigError, a menos que se establezca optional: true. Kubernetes nunca adivina otra key.", ["Kubernetes nunca sustituye una key faltante por una cadena vacía, a menos que se establezca optional: true, en cuyo caso la variable simplemente no se define.", "Sin optional: true, la key faltante es un error; el contenedor no inicia ignorando la variable.", "Kubernetes nunca adivina otra key; las referencias deben nombrar exactamente una key existente.", null]],
  "ck68": ["El Pod web debe ejecutarse con el ServiceAccount web-sa, que ya existe. ¿Qué campo del Pod lo establece?", ["metadata.serviceAccount: web-sa", "spec.serviceAccountName: web-sa", "spec.containers[].serviceAccount: web-sa", "spec.securityContext.serviceAccount: web-sa"], "spec.serviceAccountName selecciona el ServiceAccount para todo el Pod. No es una configuración por contenedor ni de securityContext.", ["El ServiceAccount se establece en spec, no en metadata, así que metadata.serviceAccount no tiene efecto.", null, "Los ServiceAccounts se eligen por Pod, no por contenedor, así que no existe un campo serviceAccount a nivel de contenedor.", "securityContext controla UIDs, capabilities y configuraciones similares; no tiene un campo serviceAccount."]],
  "ck69": ["Una app nunca llama a la API de Kubernetes. ¿Cómo evitas que se monte un token de API en sus Pods?", ["Eliminar el ServiceAccount default", "Quitar el RoleBinding del Pod", "Establecer readOnlyRootFilesystem: true", "Establecer automountServiceAccountToken: false"], "automountServiceAccountToken: false en el Pod o en el ServiceAccount omite el montaje del token. Eliminar el ServiceAccount default rompe la creación de Pods en el namespace.", ["Eliminar el ServiceAccount default rompe la creación de Pods en el namespace y, de todos modos, se vuelve a crear automáticamente.", "Los RoleBindings controlan lo que puede hacer el token; quitar uno igual monta el token en el Pod.", "readOnlyRootFilesystem bloquea las escrituras en el sistema de archivos del contenedor, pero no impide que se monte el volumen del token.", null]],
  "ck70": ["Un contenedor debe ejecutarse con el UID 1000 y nunca como root. ¿Qué configuraciones de securityContext son las adecuadas?", ["privileged: false y runAsGroup: 0", "fsGroup: 1000 y allowPrivilegeEscalation: true", "runAsUser: 1000 y runAsNonRoot: true", "runAsUser: 0 y readOnlyRootFilesystem: true"], "runAsUser establece el UID y runAsNonRoot hace que el kubelet se niegue a iniciar el contenedor como UID 0. privileged: false por sí solo no impide que el proceso se ejecute como root.", ["privileged: false no impide ejecutar como root, y runAsGroup: 0 establece root como grupo principal.", "fsGroup establece el grupo propietario de los volúmenes, no el UID del proceso, y permitir la escalada de privilegios debilita la seguridad.", null, "runAsUser: 0 es root, que es justo lo que se debe evitar; un sistema de archivos de solo lectura no cambia el UID."]],
  "ck71": ["Una herramienta de red en un contenedor necesita cambiar la configuración de las interfaces, pero nada más que sea privilegiado. ¿Cuál es el enfoque de mínimo privilegio?", ["Establecer privileged: true", "Quitar ALL y agregar la capability NET_ADMIN", "Ejecutar el contenedor como root con hostNetwork", "Establecer allowPrivilegeEscalation: true"], "Agregar solo NET_ADMIN después de quitar todas las capabilities otorga justo lo que necesita la herramienta. privileged: true da un acceso casi total al host.", ["privileged: true otorga casi todas las capabilities del host y acceso a dispositivos, mucho más de lo necesario para cambiar interfaces.", null, "Ejecutar como root con hostNetwork da acceso a la pila de red del nodo, lo cual es más amplio de lo que necesita el contenedor.", "allowPrivilegeEscalation: true solo permite la escalada al estilo setuid; no otorga NET_ADMIN y debilita la seguridad."]],
  "ck72": ["El namespace apps tiene la label `pod-security.kubernetes.io/enforce=restricted`. Se envía un Pod sin runAsNonRoot y sin quitar capabilities. ¿Qué pasa?", ["Pod Security Admission lo rechaza", "Se ejecuta y se registra una advertencia", "Se modifica para que cumpla y se ejecuta", "Se programa solo en nodos con taints"], "En modo enforce, los Pods que violan el estándar restricted se rechazan en la admisión. Pod Security Admission solo valida; no modifica los Pods.", [null, "Registrar una advertencia es el comportamiento del modo warn; el modo enforce rechaza el Pod.", "Pod Security Admission solo valida; nunca modifica los Pods para que cumplan.", "Pod Security Admission no influye en la programación ni en los taints; actúa en el momento de la admisión, antes de guardar el Pod."]],
  "ck73": ["¿Qué comando crea un Service ClusterIP para el Deployment web que escuche en el puerto 80 y reenvíe al puerto 8080 del contenedor?", ["kubectl expose deployment web --port=80 --target-port=8080", "kubectl create service web --port=8080:80", "kubectl expose pod web --node-port=80", "kubectl port-forward deployment/web 80:8080"], "expose copia el selector del Deployment y establece port y targetPort. port-forward solo crea un túnel desde tu máquina y no crea ningún Service.", [null, "create service necesita un subcomando de tipo como clusterip, los puertos se indican con --tcp=80:8080, y no copiaría el selector del Deployment.", "Esto expone un Pod llamado web en lugar del Deployment, y --node-port no es la opción para un Service ClusterIP.", "port-forward abre un túnel temporal desde tu máquina y no crea ningún objeto Service."]],
  "ck74": ["Un Service no tiene endpoints aunque sus Pods están Running y Ready. ¿Cuál es la causa MÁS probable?", ["El tipo de Service es ClusterIP", "El namespace no tiene una NetworkPolicy que permita el tráfico hacia los Pods", "Los Pods no tienen límites de recursos", "El selector del Service no coincide con las labels de los Pods"], "Los endpoints se construyen a partir de los Pods que coinciden con el selector y están listos. ClusterIP es el tipo normal y no bloquea los endpoints.", ["ClusterIP es el tipo de Service predeterminado y normal; no impide que se creen endpoints.", "Las NetworkPolicies filtran el tráfico, pero no afectan qué Pods aparecen en los endpoints de un Service.", "Los límites de recursos no tienen relación con la selección de endpoints, que se basa en labels y en readiness.", null]],
  "ck75": ["Los Pods del namespace shop deben llamar al Service api del namespace backend. ¿Qué nombre DNS funciona siempre?", ["api.shop.svc.cluster.local", "api.backend.svc.cluster.local", "backend.api.cluster.local", "api.svc.backend.local"], "El patrón es <service>.<namespace>.svc.<cluster-domain>. El nombre corto api solo se resolvería dentro del propio backend.", ["Este nombre apunta a un Service llamado api en el namespace shop, no al de backend.", null, "El orden es incorrecto y falta svc; el patrón es el servicio, luego el namespace, luego svc y el dominio del clúster.", "Las partes del namespace y de svc están intercambiadas y el dominio del clúster es incorrecto, así que este nombre no se resuelve."]],
  "ck76": ["Lee este Service: `type: NodePort`, `port: 80`, `targetPort: 8080`, `nodePort: 30080`. ¿Cómo llega un cliente externo a la app?", ["<node-ip>:80 por HTTP", "<cluster-ip>:30080 por HTTP", "<node-ip>:30080 por HTTP", "<pod-ip>:30080 por HTTP"], "NodePort abre el 30080 en cada nodo y reenvía al puerto 80 del Service y luego al 8080 de los Pods. La ClusterIP solo es accesible dentro del clúster.", ["El puerto 80 es el puerto del Service en la ClusterIP; no se abre en la IP del nodo.", "El 30080 se abre en las IP de los nodos, y de todos modos la ClusterIP solo es accesible desde dentro del clúster.", null, "Los Pods escuchan en el targetPort 8080; nada escucha en el 30080 en la IP del Pod, y las IP de los Pods normalmente no son accesibles desde afuera."]],
  "ck77": ["Un StatefulSet necesita registros DNS para cada Pod (db-0.db, db-1.db) en lugar de una sola IP virtual. ¿Qué configuración de Service lo proporciona?", ["type: ExternalName", "clusterIP: None (headless)", "sessionAffinity: ClientIP", "externalTrafficPolicy: Local"], "Un Service headless no tiene IP virtual y devuelve registros DNS por Pod para los miembros del StatefulSet. sessionAffinity solo fija clientes a Pods detrás de una ClusterIP normal.", ["ExternalName devuelve un CNAME a un host externo y no tiene relación con los Pods del StatefulSet.", null, "sessionAffinity fija un cliente a un Pod detrás de una IP virtual normal; no crea registros DNS por Pod.", "externalTrafficPolicy: Local controla el enrutamiento local al nodo del tráfico externo, no los nombres DNS por Pod."]],
  "ck78": ["Las apps deben llamar a una base de datos externa como `db` dentro del clúster, que corresponde a db.example.com. ¿Qué tipo de Service es el adecuado?", ["ClusterIP sin selector", "LoadBalancer", "NodePort", "ExternalName"], "ExternalName devuelve un CNAME de DNS hacia el host externo. Una ClusterIP sin selector, en cambio, necesita endpoints manuales con direcciones IP.", ["Una ClusterIP sin selector necesita endpoints manuales con direcciones IP; no puede apuntar a un nombre de host DNS.", "Un LoadBalancer expone Pods del clúster a clientes externos, la dirección opuesta a este requisito.", "NodePort expone Pods del clúster en puertos de los nodos; no crea un alias de un nombre de host externo.", null]],
  "ck79": ["Lee esta NetworkPolicy: `podSelector: {}`, `policyTypes: [Ingress]` y sin reglas de ingress. ¿Qué hace?", ["Deniega todo el ingress a todos los Pods del namespace", "Permite todo el ingress a todos los Pods del namespace", "Deniega todo el egress del namespace", "No tiene efecto porque no hay reglas"], "Un podSelector vacío selecciona todos los Pods; con Ingress en policyTypes y sin reglas, no se permite tráfico entrante. El egress no se toca porque no está en la lista.", [null, "Con Ingress en policyTypes y una lista de ingress vacía, no entra nada; permitir todo requiere una regla con una entrada vacía.", "Egress no está en policyTypes, así que esta política no restringe el tráfico saliente.", "Una lista de reglas vacía tiene significado: selecciona todos los Pods y no permite ingress, que es el patrón default-deny."]],
  "ck80": ["Aplicas una NetworkPolicy válida, pero el tráfico que debería bloquear sigue fluyendo. El clúster usa un CNI sin soporte de políticas. ¿Por qué?", ["Las NetworkPolicies requieren reiniciar kube-proxy", "Las NetworkPolicies solo aplican a Services NodePort", "El plugin CNI debe aplicar las NetworkPolicies", "Las políticas solo tienen efecto en namespaces nuevos"], "La API guarda las NetworkPolicies, pero quien las aplica es el plugin de red (como Calico o Cilium). kube-proxy maneja el enrutamiento de los Services, no las políticas.", ["kube-proxy implementa el enrutamiento de los Services, no las NetworkPolicies, así que reiniciarlo no cambia nada.", "Las NetworkPolicies aplican al tráfico de los Pods en general, sin importar el tipo de Service.", null, "Las políticas aplican a los Pods que coinciden en namespaces existentes en cuanto un CNI que las aplica las detecta."]],
  "ck81": ["Una NetworkPolicy sobre los Pods de backend tiene un solo elemento `from` que contiene tanto `namespaceSelector: {matchLabels: {team: web}}` como `podSelector: {matchLabels: {role: fe}}`. ¿Quién tiene permitido el acceso?", ["Cualquier Pod de los namespaces team=web, más cualquier Pod role=fe", "Solo los Pods role=fe del namespace backend", "Solo los Pods role=fe de los namespaces con la label team=web", "Todos los Pods de todos los namespaces"], "Los selectores dentro del mismo elemento from se combinan con AND. Ponerlos como dos elementos separados los combinaría con OR y permitiría ambos grupos.", ["Ese sería el comportamiento OR de dos elementos from separados; dentro de un mismo elemento los selectores se combinan con AND.", "El namespaceSelector amplía el alcance a los namespaces team=web en lugar de limitarlo al namespace backend.", null, "Los selectores restringen el tráfico a un conjunto específico de Pods; nada aquí permite todos los namespaces."]],
  "ck82": ["Después de agregar una política default-deny de egress, los Pods no pueden resolver ningún nombre de Service. ¿Qué debes permitir?", ["Egress hacia kube-dns en el puerto 53 UDP y TCP", "Egress hacia el API server en el puerto 6443", "Ingress desde kube-proxy en el puerto 10256", "Egress hacia el kubelet del nodo en el puerto 10250"], "Las consultas DNS van a los Pods de DNS del clúster en el puerto 53, que el default-deny de egress bloquea. El API server no participa en la resolución de nombres.", [null, "La resolución de nombres no pasa por el API server, así que permitir el 6443 no resuelve las consultas DNS.", "El problema es el tráfico DNS saliente, no el entrante, y el puerto de health de kube-proxy no tiene relación con DNS.", "El puerto del kubelet se usa para logs y exec desde el API server; los Pods no resuelven nombres a través de él."]],
  "ck83": ["Solo los Pods con la label app=frontend pueden llegar a los Pods con la label app=api en el TCP 8080. ¿Qué regla de ingress va en una política que selecciona app=api?", ["from: ipBlock 0.0.0.0/0; ports: TCP 8080", "to: podSelector app=frontend; ports: TCP 8080", "from: namespaceSelector app=frontend; ports: 8080", "from: podSelector app=frontend; ports: TCP 8080"], "Las reglas de ingress usan peers from, y un podSelector coincide con los Pods del namespace de la política. namespaceSelector coincidiría con labels de namespaces, no de Pods.", ["ipBlock 0.0.0.0/0 permite tráfico desde cualquier IP, no solo desde los Pods de frontend.", "Los peers to se usan en las reglas de egress; una regla de ingress necesita from.", "namespaceSelector coincide con labels de los namespaces, no de los Pods, así que no seleccionaría los Pods app=frontend.", null]],
  "ck84": ["Se crea un Ingress, pero `kubectl get ingress` no muestra ninguna dirección y las solicitudes nunca llegan a la app. ¿Qué es lo MÁS probable que falte?", ["Un Service NodePort en kube-system", "Un Ingress controller para su ingressClassName", "Un Service de tipo LoadBalancer en la aplicación de backend", "Una NetworkPolicy que permita el puerto 443"], "El recurso Ingress es solo configuración; un controlador como ingress-nginx debe implementarlo. Los backends pueden ser Services ClusterIP comunes.", ["No se requieren Services NodePort en kube-system; sin un controlador, nada implementa el Ingress.", null, "Los backends pueden ser Services ClusterIP comunes; no se necesita LoadBalancer detrás de un Ingress.", "Una NetworkPolicy no le daría una dirección al Ingress; la dirección faltante significa que ningún controlador lo tomó."]],
  "ck85": ["La ruta de un Ingress es `/api` con `pathType: Prefix`. ¿Qué solicitud coincide?", ["/apis", "/API", "/v1/api", "/api/v1/users"], "Prefix compara segmentos completos de la ruta, así que /api/v1/users coincide pero /apis no. La comparación distingue mayúsculas de minúsculas, así que /API falla.", ["La coincidencia por Prefix funciona con segmentos completos de la ruta, así que /apis es un segmento distinto y no coincide con /api.", "La comparación de rutas distingue mayúsculas de minúsculas, así que /API no coincide con /api.", "El prefijo debe coincidir desde el inicio de la ruta; /v1/api empieza con /v1.", null]],
  "ck86": ["¿Qué comando crea un Ingress llamado web que enruta el host shop.example.com, todas las rutas, al Service web en el puerto 80?", ["kubectl create service ingress web --host=shop.example.com", "kubectl expose ingress web --host=shop.example.com --port=80", "kubectl create ingress web --rule=\"shop.example.com/*=web:80\"", "kubectl apply ingress web shop.example.com=web:80"], "create ingress usa --rule=host/path=service:port, y /* crea una ruta de tipo Prefix. expose crea Services, no Ingresses.", ["create service no tiene un subtipo ingress, y los Services no pueden hacer enrutamiento HTTP por host.", "kubectl expose crea Services, no objetos Ingress.", null, "kubectl apply necesita un archivo de manifiesto y no acepta una regla como argumentos posicionales."]],
  "ck87": ["Un Ingress debe servir HTTPS para shop.example.com. ¿A qué hace referencia su sección tls?", ["Un ConfigMap que contiene el certificado", "Un Secret de tipo kubernetes.io/tls", "Un token de ServiceAccount", "Un PersistentVolumeClaim con los archivos de la clave"], "La sección tls nombra el host y un Secret que contiene tls.crt y tls.key, creado con kubectl create secret tls. Los ConfigMaps no se usan para claves.", ["La sección tls de un Ingress solo hace referencia a Secrets; los ConfigMaps no se usan para certificados ni claves.", null, "Los tokens de ServiceAccount autentican ante la API de Kubernetes y no tienen nada que ver con servir HTTPS.", "Los Ingress controllers no leen certificados desde volúmenes; la sección tls nombra un Secret."]],
  "ck88": ["Necesitas probar el Service db en el puerto 5432 desde tu laptop sin exponerlo fuera del clúster. ¿Qué comando usas?", ["kubectl port-forward svc/db 5432:5432", "kubectl expose svc db --type=NodePort", "kubectl proxy --port=5432", "kubectl run tunnel --port=5432"], "port-forward crea un túnel de un puerto local hacia el Service a través del API server sin cambiar el clúster. Cambiar a NodePort lo expondría en todos los nodos.", [null, "Cambiar a NodePort expone la base de datos en todos los nodos, que es justo lo que se debe evitar.", "kubectl proxy expone la API de Kubernetes en un puerto local, no una conexión TCP directa al Service db.", "kubectl run crea un Pod nuevo y no crea un túnel hacia tu laptop."]],
  "ck89": ["Un Service define `port: 80` y `targetPort: http`. ¿A qué se refiere targetPort: http?", ["A un containerPort con nombre llamado http en la spec del Pod", "Al protocolo HTTP, que obliga a usar enrutamiento de Capa 7", "Al puerto 80 del nodo", "A una regla de Ingress llamada http"], "targetPort puede hacer referencia a un containerPort por nombre, así que los Pods pueden usar distintos números de puerto detrás del mismo nombre. Los Services no hacen enrutamiento de Capa 7.", [null, "Los Services funcionan en la Capa 4; un nombre de puerto como http no obliga a ningún enrutamiento que entienda el protocolo.", "Los puertos de los nodos se establecen con nodePort; targetPort se refiere al lado del Pod, no al nodo.", "Los Services no hacen referencia a reglas de Ingress; targetPort nombra un puerto del contenedor."]],
  "ck90": ["Un curl a un Service agota el tiempo de espera. Los endpoints muestran las IP correctas de los Pods en el puerto 80, pero los contenedores escuchan en el 8080. ¿Qué está mal?", ["El selector del Service es incorrecto", "CoreDNS no se está ejecutando", "Los Pods están fallando sus readiness probes y no están Ready", "El targetPort del Service no coincide con el puerto del contenedor"], "Los endpoints llevan el targetPort, así que el tráfico va al 80, donde nada escucha. Un selector incorrecto daría, en cambio, una lista de endpoints vacía.", ["Un selector incorrecto dejaría los endpoints vacíos o apuntando a otros Pods; aquí los endpoints son los Pods correctos.", "DNS funciona, ya que el Service se resuelve y tiene endpoints; el timeout se debe al puerto incorrecto.", "Los Pods que fallan la readiness no aparecerían como endpoints listos, pero aquí sí aparecen los Pods correctos.", null]],
  "x1": ["Un Job de importación de datos sigue creando Pods nuevos después de cada falla, y el equipo quiere que Kubernetes se rinda después de cuatro reintentos fallidos. ¿Qué campo del Job deben establecer?", ["backoffLimit: 4", "activeDeadlineSeconds: 4", "completions: 4", "parallelism: 4 con restartPolicy: Never"], "backoffLimit es la cantidad de reintentos antes de que el Job se marque como fallido. activeDeadlineSeconds es tentador porque también detiene un Job, pero mide segundos transcurridos en lugar de intentos fallidos.", [null, "activeDeadlineSeconds es un límite de tiempo real en segundos para todo el Job, no un conteo de reintentos.", "completions establece cuántos Pods exitosos necesita el Job; no limita cuántas fallas se toleran.", "parallelism controla cuántos Pods se ejecutan a la vez; con restartPolicy Never las fallas siguen contando para backoffLimit, que queda en su valor predeterminado."]],
  "x2": ["Un Job de reportes debe detenerse si sigue en ejecución 10 minutos después de iniciar, sin importar cuántos reintentos queden. ¿Qué configuración de la spec del Job lo hace?", ["backoffLimit: 600", "activeDeadlineSeconds: 600", "ttlSecondsAfterFinished: 600", "terminationGracePeriodSeconds: 600"], "activeDeadlineSeconds limita el tiempo total de ejecución del Job; una vez superado, sus Pods se terminan y el Job falla con DeadlineExceeded. ttlSecondsAfterFinished es tentador, pero solo elimina los Jobs terminados.", ["backoffLimit cuenta los reintentos fallidos; un valor de 600 permitiría muchos más intentos en lugar de aplicar un límite de tiempo.", null, "ttlSecondsAfterFinished solo limpia un Job después de que ya terminó; nunca detiene uno en ejecución.", "Este es el tiempo que tiene un Pod para apagarse después de que se le pide detenerse, no un límite de cuánto puede durar el Job."]],
  "x3": ["Una app siempre se conecta a localhost:6379. Un segundo contenedor del mismo Pod acepta esa conexión y la reenvía al shard de Redis correcto en otra parte del clúster. ¿Qué patrón de múltiples contenedores es este?", ["Adapter", "Init container", "Ambassador", "Ephemeral container"], "Un contenedor ambassador hace de proxy de las conexiones del contenedor principal hacia servicios externos, así que la app solo habla con localhost. Adapter es tentador porque también es un contenedor auxiliar, pero transforma la salida en lugar de intermediar conexiones.", ["Un adapter transforma la salida del contenedor principal (por ejemplo, métricas o logs) a un formato estándar; no hace de proxy de las conexiones salientes.", "Un init container se ejecuta hasta completarse antes de que inicie la app, así que no puede hacer de proxy del tráfico durante la vida de la app.", null, "Los ephemeral containers se agregan temporalmente para depurar con kubectl debug, no se declaran como un proxy permanente."]],
  "x4": ["Una app heredada escribe métricas en su propio formato de texto, pero el sistema de monitoreo solo recolecta métricas en formato Prometheus. No puedes cambiar la app. ¿Qué diseño es el MÁS adecuado?", ["Un init container que reescriba las métricas una vez", "Un contenedor ambassador que reenvíe las métricas sin cambios", "Una readiness probe que exporte las métricas", "Un contenedor adapter que convierta las métricas"], "El patrón adapter coloca un contenedor auxiliar junto a la app que presenta la salida de la app en una interfaz estándar, en este caso métricas de Prometheus. Un ambassador es tentador, pero solo retransmite el tráfico sin transformarlo.", ["Un init container termina antes de que inicie la app, así que no puede convertir las métricas que la app sigue produciendo mientras se ejecuta.", "Un ambassador hace de proxy de conexiones; reenviar los datos sin cambios los deja en el formato que el sistema de monitoreo no puede leer.", "Las probes solo informan la salud al kubelet; no pueden publicar ni traducir métricas de la aplicación.", null]],
  "x5": ["Una imagen ya incluye varios archivos en /etc/app. Debes agregar config.yaml del ConfigMap app-cfg en ese directorio sin ocultar los archivos existentes. ¿Qué volumeMount funciona?", ["mountPath: /etc/app con readOnly: true", "mountPath: /etc/app con items que enumeren solo config.yaml", "mountPath: /etc/app/config.yaml con subPath: config.yaml", "envFrom con configMapRef app-cfg y sin volumen"], "subPath monta una sola key del volumen como un archivo en la ruta indicada, dejando intacto el resto del directorio. Usar items es tentador, pero el volumen sigue montado sobre todo el directorio.", ["Montar el volumen en /etc/app reemplaza todo el directorio con el contenido del volumen, sea de solo lectura o no, así que los archivos de la imagen desaparecen.", "items limita qué keys se proyectan, pero el volumen sigue cubriendo /etc/app y oculta los archivos existentes.", null, "envFrom convierte las keys en variables de entorno; nunca crea un archivo en /etc/app."]],
  "x6": ["Un sidecar de envío de logs debe leer los archivos que el contenedor principal escribe en un emptyDir compartido, y no debe poder modificarlos. ¿Cuál es la forma más sencilla de aplicarlo?", ["Establecer readOnly: true en el volumeMount del sidecar", "Establecer readOnlyRootFilesystem: true en el sidecar", "Establecer medium: ReadOnly en el emptyDir", "Montar el emptyDir solo en el contenedor principal"], "readOnly se establece por volumeMount, así que el contenedor principal puede seguir escribiendo mientras el montaje del sidecar es de solo lectura. readOnlyRootFilesystem es tentador, pero no afecta a los volúmenes montados.", [null, "readOnlyRootFilesystem aplica al sistema de archivos raíz del propio contenedor, no a los volúmenes montados, así que el sidecar podría seguir escribiendo en el emptyDir.", "emptyDir admite medium Memory o el disco predeterminado; no existe un medium ReadOnly.", "En ese caso el sidecar no vería los archivos de log en absoluto, así que no podría enviarlos."]],
  "x7": ["Una app espera su archivo de configuración (de un ConfigMap), su clave TLS (de un Secret) y las labels de su Pod (de la downward API), todo en un solo directorio, /etc/app. ¿Qué tipo de volumen lo proporciona en un solo montaje?", ["emptyDir", "configMap con un Secret enumerado en items", "hostPath apuntando a /etc/app en el nodo", "projected"], "Un volumen projected combina orígenes como configMap, secret, downwardAPI y serviceAccountToken en un solo directorio. Un volumen configMap es tentador, pero solo puede tomar keys de un único ConfigMap.", ["emptyDir empieza vacío; no puede traer por sí solo datos de ConfigMaps, Secrets o de la downward API.", "Un volumen configMap solo puede proyectar keys de un ConfigMap; items no puede hacer referencia a un Secret.", "hostPath expone un directorio del nodo y no tiene nada que ver con ConfigMaps ni Secrets; además debilita el aislamiento.", null]],
  "x8": ["Un PVC omite storageClassName, y el clúster tiene una StorageClass marcada como predeterminada con un aprovisionador dinámico. ¿Qué pasa cuando se crea el PVC?", ["El PVC se queda en Pending hasta que un administrador cree un PV a mano", "La StorageClass predeterminada aprovisiona un PV que coincide", "El PVC se vincula a cualquier PV existente sin importar su tamaño", "El Pod recurre a un volumen emptyDir"], "Cuando se omite storageClassName, la StorageClass predeterminada se aplica al claim y su aprovisionador crea un PV de forma dinámica. Quedarse en Pending es tentador, pero ese es el comportamiento cuando no existe una clase predeterminada.", ["Eso solo pasa cuando no existe una StorageClass predeterminada o no hay aprovisionamiento dinámico disponible.", null, "La vinculación siempre requiere un PV que cumpla el tamaño y el access mode solicitados.", "Kubernetes nunca reemplaza en silencio un PVC por un emptyDir; el Pod esperaría el claim."]],
  "x9": ["Tres réplicas de un Deployment, repartidas en distintos nodos, deben escribir en el mismo directorio compartido. ¿Qué access mode de PVC se requiere, suponiendo que el backend de almacenamiento lo admite?", ["ReadWriteOnce", "ReadWriteMany", "ReadOnlyMany", "ReadWriteOncePod"], "ReadWriteMany permite que muchos nodos monten el volumen en lectura-escritura a la vez, lo que ofrecen backends de archivos compartidos como NFS. ReadWriteOnce es tentador porque es el predeterminado habitual, pero está limitado a un nodo.", ["ReadWriteOnce permite el montaje en lectura-escritura de un solo nodo, así que las réplicas de otros nodos no podrían montarlo.", null, "ReadOnlyMany permite que muchos nodos monten el volumen, pero solo para lectura, así que las réplicas no podrían escribir.", "ReadWriteOncePod restringe el volumen a un solo Pod, lo cual es aún más estricto que ReadWriteOnce."]],
  "x10": ["Un Dockerfile de Python ejecuta `COPY . .` y luego `RUN pip install -r requirements.txt`. Cada pequeño cambio de código hace que el build reinstale todas las dependencias. ¿Cuál es la MEJOR solución?", ["Agregar --no-cache-dir a pip install", "Encadenar todas las líneas RUN en una sola instrucción", "Construir con --no-cache cada vez", "Copiar requirements.txt e instalarlo antes de copiar el resto"], "La caché de cada instrucción se invalida cuando cambian sus entradas. Copiar primero solo requirements.txt hace que la capa de instalación se reutilice hasta que cambien las dependencias. Encadenar las líneas RUN es tentador, pero el COPY . . temprano sigue invalidando la caché.", ["Eso solo evita que pip conserve su propia caché de descargas; la capa se sigue reconstruyendo cada vez que cambia cualquier archivo fuente.", "Unir líneas RUN reduce la cantidad de capas, pero no hace nada respecto del COPY que invalida la caché primero.", "--no-cache desactiva por completo la caché de capas, lo que hace cada build más lento, no más rápido.", null]],
  "x11": ["Una imagen tiene `ENTRYPOINT [\"/app/server\"]` y `CMD [\"--port=8080\"]`. Un Pod establece `command: [\"/bin/sh\", \"-c\"]` y ningún args. ¿Qué ejecuta el contenedor?", ["/bin/sh -c sin argumentos, ignorando el CMD de la imagen", "/bin/sh -c /app/server --port=8080", "/bin/sh -c --port=8080", "/app/server --port=8080"], "Si un Pod establece command pero no args, Kubernetes usa solo ese command e ignora tanto el ENTRYPOINT como el CMD de la imagen. Esperar que el CMD se conserve como argumentos es el error tentador; debes establecer args explícitamente.", [null, "Establecer command reemplaza el ENTRYPOINT; no agrega el ENTRYPOINT anterior como argumento.", "Cuando se establece command y no args, el CMD de la imagen también se ignora, así que no se pasa --port=8080.", "El command del Pod sobrescribe el ENTRYPOINT de la imagen, así que no es /app/server lo que inicia."]],
  "x12": ["Un colega te da /tmp/app.tar, creado con docker save a partir de la imagen app:1.0. Debes cargarlo y etiquetarlo como registry.local/app:1.0. ¿Qué comandos lo hacen?", ["docker import /tmp/app.tar registry.local/app:1.0", "docker pull /tmp/app.tar, luego docker tag app:1.0 registry.local/app:1.0", "docker load -i /tmp/app.tar, luego docker tag app:1.0 registry.local/app:1.0", "docker run -i /tmp/app.tar, luego docker commit registry.local/app:1.0"], "docker load restaura las imágenes guardadas con docker save, incluidos los tags y los metadatos, y docker tag agrega el nuevo nombre. docker import es tentador porque también lee archivos tar, pero es la contraparte de docker export y pierde la configuración de la imagen.", ["docker import construye una imagen a partir de un tarball de sistema de archivos y descarta metadatos como el ENTRYPOINT; está pensado para la salida de docker export.", "docker pull descarga de un registro por nombre; no puede leer un archivo tar local.", null, "docker run necesita una imagen, no un archivo tar, y commit tomaría una instantánea de un contenedor en lugar de restaurar la imagen guardada."]],
  "x13": ["Los Pods nuevos del Deployment web pasan su readiness probe y luego suelen caerse unos 20 segundos después, pero el rollout pasa de inmediato al siguiente lote. ¿Qué campo hace que el rollout espere antes de considerar disponibles a los Pods nuevos?", ["progressDeadlineSeconds: 30", "revisionHistoryLimit: 30", "terminationGracePeriodSeconds: 30", "minReadySeconds: 30"], "minReadySeconds exige que un Pod nuevo permanezca Ready durante esa cantidad de segundos antes de contar como disponible, así que un Pod que se cae a los 20 segundos frena el rollout. progressDeadlineSeconds es tentador, pero solo informa un rollout atascado.", ["progressDeadlineSeconds establece cuándo se informa como fallido un rollout estancado; no retrasa el momento en que los Pods cuentan como disponibles.", "revisionHistoryLimit controla cuántos ReplicaSets anteriores se conservan para el rollback, no el ritmo del rollout.", "Este es el periodo de gracia de apagado de los Pods que se detienen; no afecta cuándo se confía en los Pods nuevos.", null]],
  "x14": ["Un Deployment tiene 10 réplicas con `maxSurge: 0` y `maxUnavailable: 20%`. ¿Cuál es la cantidad mínima de Pods disponibles durante una actualización rolling?", ["10", "12", "8", "5"], "El 20% de 10 es 2, así que como máximo dos Pods pueden no estar disponibles, lo que deja al menos 8 disponibles. 12 es tentador si confundes maxUnavailable con maxSurge, pero aquí maxSurge es 0.", ["Eso requeriría maxUnavailable 0; aquí hasta dos Pods pueden no estar disponibles a la vez.", "12 sería el máximo con un surge de 2; con maxSurge 0 el total nunca supera 10.", null, "5 significaría un 50% no disponible, mucho más que el 20% permitido."]],
  "x15": ["El tráfico se duplicó y el Deployment web necesita 5 réplicas ahora mismo. ¿Qué comando lo hace?", ["kubectl set replicas deployment/web 5", "kubectl scale deployment web --replicas=5", "kubectl rollout scale deployment/web --count=5", "kubectl autoscale deployment web --replicas=5"], "kubectl scale cambia directamente la cantidad de réplicas y no crea una revisión nueva. kubectl autoscale es tentador, pero crea un HorizontalPodAutoscaler en lugar de establecer un número fijo.", ["kubectl set admite subcomandos como image, env y resources, pero no replicas.", null, "kubectl rollout tiene status, history, undo, pause, resume y restart; no existe un subcomando scale.", "kubectl autoscale crea un HPA con --min y --max; no tiene una opción --replicas y no establece una cantidad fija."]],
  "x16": ["Antes de hacer rollback, quieres ver la plantilla de Pod que usó el Deployment web en la revisión 2. ¿Qué comando la muestra?", ["kubectl rollout history deployment/web --revision=2", "kubectl rollout undo deployment/web --to-revision=2", "kubectl get replicaset web --revision=2", "kubectl describe deployment web --history=2"], "kubectl rollout history con --revision imprime la plantilla de Pod registrada para esa revisión sin cambiar nada. rollout undo es tentador, pero ejecuta el rollback.", [null, "Esto realmente hace rollback a la revisión 2 en lugar de solo mostrarla.", "kubectl get no tiene una opción --revision, y los nombres de los ReplicaSets incluyen un sufijo de hash.", "kubectl describe no tiene una opción --history; solo muestra la spec actual y los eventos."]],
  "x17": ["Agregaste un repo de Helm hace varias semanas. Su sitio ahora muestra una versión más nueva del chart, pero helm install sigue eligiendo la versión anterior. ¿Qué debes ejecutar primero?", ["helm repo update", "helm repo add otra vez con el mismo nombre", "helm upgrade --install con --force", "helm dependency update"], "Helm usa un índice en caché local de cada repo; helm repo update descarga el índice más reciente para que las versiones nuevas de los charts sean visibles. helm dependency update es tentador por su nombre, pero trabaja sobre las dependencias propias de un chart.", [null, "Volver a agregar un nombre de repo existente no refresca nada; helm repo update es el comando que obtiene el índice más reciente.", "--force cambia cómo se reemplazan los recursos; no refresca el índice local de charts.", "Esto refresca las dependencias listadas en el Chart.yaml de un chart local, no el índice de tus repos configurados."]],
  "x18": ["Quieres encontrar charts llamados redis en los repositorios de Helm que ya agregaste. ¿Qué comando usas?", ["helm search hub redis", "helm search repo redis", "helm list redis", "helm show chart redis"], "helm search repo busca en los charts de los repos que agregaste con helm repo add. helm search hub es tentador, pero busca en el hub público, no en tus repos configurados.", ["search hub consulta Artifact Hub en línea en lugar de los repositorios configurados en tu máquina.", null, "helm list muestra los releases instalados, no los charts disponibles en los repositorios.", "helm show chart imprime los metadatos de un chart que nombras exactamente; no hace búsquedas."]],
  "x19": ["Ejecutas `helm upgrade web ./chart -f prod.yaml --set replicaCount=4`, y prod.yaml contiene replicaCount: 2. ¿Cuántas réplicas recibe el release?", ["2, porque los archivos de valores sobrescriben a --set", "El valor predeterminado del chart, porque los dos valores entran en conflicto", "4, porque --set sobrescribe a los archivos de valores", "Ninguna, porque Helm rechaza los valores en conflicto"], "Helm combina los valores predeterminados del chart, luego los archivos -f en orden y después los valores de --set, así que --set gana. Pensar que gana el archivo es el error tentador porque aparece primero en la línea de comandos.", ["El orden es al revés: los valores de --set tienen prioridad sobre los de los archivos -f.", "Helm combina los valores por prioridad; un conflicto no hace que se vuelva al valor predeterminado del chart.", null, "Helm no rechaza los valores que se superponen; los resuelve por prioridad."]],
  "x20": ["Un pipeline de CI despliega el release api con el mismo comando cada vez. El release puede existir o no todavía. ¿Qué comando único lo instala la primera vez y lo actualiza después?", ["helm install api ./chart --replace", "helm rollback api 0", "helm template api ./chart", "helm upgrade --install api ./chart"], "helm upgrade --install actualiza el release si existe y lo instala si no, lo que permite repetirlo con seguridad. helm install --replace es tentador, pero falla cuando el release sigue desplegado.", ["--replace solo reutiliza el nombre de un release eliminado; falla si el release ya está desplegado.", "rollback devuelve un release existente a una revisión anterior; no puede instalar uno nuevo.", "helm template solo renderiza los manifiestos localmente; no instala ni actualiza nada.", null]],
  "x21": ["El release web del namespace frontend ya no se necesita. ¿Qué comando lo elimina junto con los recursos que creó?", ["helm delete-release web --namespace frontend", "kubectl delete namespace frontend", "helm uninstall web -n frontend", "helm rollback web 0 -n frontend"], "helm uninstall elimina los recursos del release y su registro de release en ese namespace. Eliminar el namespace es tentador porque también elimina el release, pero borra además cargas de trabajo no relacionadas.", ["No existe el comando delete-release; helm uninstall (con el alias helm delete) es el correcto.", "Esto elimina todo lo del namespace, no solo este release, y es mucho más amplio de lo que se pidió.", null, "rollback mueve un release a otra revisión; no lo elimina."]],
  "x22": ["En un overlay de Kustomize, cada recurso debe desplegarse en el namespace staging, aunque los manifiestos base no tienen namespace. ¿Qué campo de kustomization.yaml lo hace?", ["namespace: staging", "namePrefix: staging-", "labels con namespace: staging", "commonAnnotations con namespace: staging"], "El campo namespace establece metadata.namespace en cada recurso con namespace que genera Kustomize. namePrefix es tentador porque los overlays también lo usan a menudo, pero solo cambia los nombres.", [null, "namePrefix cambia los nombres de los recursos, no el namespace en el que se crean.", "Agregar una label llamada namespace solo etiqueta los recursos; no los coloca en ese namespace.", "Las annotations son solo metadatos y no cambian dónde se crea un recurso."]],
  "x23": ["Un overlay usa configMapGenerator para crear app-cfg, y un Deployment hace referencia a app-cfg. Cuando cambias un valor y ejecutas kubectl apply -k, el Deployment hace rollout de Pods nuevos. ¿Por qué?", ["kubectl apply -k siempre reinicia todos los Deployments", "El kubelet reinicia los Pods cada vez que cambia un ConfigMap", "configMapGenerator agrega una annotation de rollout restart", "El nombre del ConfigMap recibe un nuevo hash de contenido, y Kustomize actualiza la referencia"], "De forma predeterminada, los ConfigMaps generados reciben un sufijo de nombre calculado a partir de su contenido, y Kustomize reescribe las referencias a él. Por eso cambia la plantilla del Pod y se dispara un rollout. Culpar al kubelet es tentador, pero no reinicia Pods por cambios en ConfigMaps.", ["apply -k solo cambia lo que es distinto; los Deployments con una plantilla de Pod sin cambios no hacen rollout.", "El kubelet nunca reinicia Pods porque cambió un ConfigMap; los archivos montados se actualizan en su lugar y las variables de entorno quedan como estaban.", "Kustomize no agrega annotations de reinicio; el rollout viene del nombre del ConfigMap que cambió en la plantilla del Pod.", null]],
  "x24": ["Un Deployment base web tiene 2 réplicas. Solo el overlay prod debe ejecutar 5 réplicas, y los demás overlays deben mantener 2. ¿Cuál es la forma correcta de hacerlo?", ["Editar replicas en el deployment.yaml base", "Agregar un patch en el overlay prod que establezca spec.replicas: 5 para web", "Establecer namePrefix: prod- y replicas en labels", "Ejecutar kubectl scale después de cada apply -k"], "Los overlays personalizan una base compartida mediante patches (o el campo replicas), así que solo cambia la salida de prod. Editar la base es tentador porque es rápido, pero cambia todos los entornos.", ["Cambiar la base afecta a todos los overlays construidos a partir de ella, no solo a prod.", null, "Las labels son metadatos; poner una label replicas no cambia la cantidad de réplicas.", "Un escalado manual se pierde la próxima vez que se aplica el overlay y no queda declarado en él."]],
  "x25": ["Estás escribiendo un Deployment a mano y necesitas ver qué campos son válidos bajo spec.strategy en este clúster. ¿Qué comando los muestra?", ["kubectl api-resources deployment.spec.strategy", "kubectl explain deployment.spec.strategy", "kubectl describe deployment.spec.strategy", "kubectl get deployment --schema=strategy"], "kubectl explain lee el esquema de la API del clúster y documenta cualquier ruta de campo, lo que es útil sin conexión durante el examen. api-resources es tentador porque también lee información de la API, pero solo a nivel de tipo de recurso.", ["api-resources enumera los tipos de recursos y sus grupos; no describe campos.", null, "describe muestra el estado de objetos existentes; no documenta el esquema.", "kubectl get no tiene una opción --schema."]],
  "x26": ["Un manifiesto antiguo define un HorizontalPodAutoscaler con `apiVersion: autoscaling/v2beta2` y un clúster actual lo rechaza. ¿Qué apiVersion debe usar?", ["autoscaling/v1beta1", "apps/v1", "metrics.k8s.io/v1", "autoscaling/v2"], "Las APIs beta del HPA se eliminaron y se reemplazaron por la estable autoscaling/v2, que conserva el soporte para múltiples métricas. metrics.k8s.io es tentador porque los HPA usan métricas, pero es otra API.", ["No existe v1beta1 para autoscaling; la versión estable anterior es autoscaling/v1.", "apps/v1 es para Deployments, StatefulSets y cargas de trabajo similares, no para HPAs.", "metrics.k8s.io es la API de métricas que lee el HPA, no el grupo de API del propio objeto HPA.", null]],
  "x27": ["Un Pod nuevo se queda en Pending. kubectl describe muestra `0/3 nodes are available: 3 Insufficient cpu`. ¿Cuál es la solución MÁS probable?", ["Reducir el CPU request del Pod o agregar capacidad de nodos", "Aumentar el CPU limit del Pod", "Agregar una liveness probe", "Reiniciar el kubelet en cada nodo"], "El scheduler coloca los Pods solo donde la suma de los requests cabe en la CPU asignable de un nodo, así que el request debe caber o la capacidad debe crecer. Aumentar el limit es tentador, pero los limits no participan en la programación.", [null, "La programación usa los requests, no los limits, así que aumentar el limit no ayuda a que el Pod quepa.", "Las probes solo se ejecutan después de que un Pod se programa e inicia; no afectan la ubicación.", "Los nodos no están fallando; simplemente no tienen suficiente CPU sin solicitar para este Pod."]],
  "x28": ["Necesitas las últimas 50 líneas de log de la última hora del Deployment api, sin buscar el nombre de un Pod. ¿Qué comando usas?", ["kubectl logs api --lines=50 --age=1h", "kubectl get logs deployment api --tail=50", "kubectl logs deploy/api --tail=50 --since=1h", "kubectl describe deploy/api --tail=50 --since=1h"], "kubectl logs acepta deploy/<name> y elige uno de sus Pods, con --tail para limitar las líneas y --since para limitar el tiempo. Usar solo el nombre es tentador, pero se busca como un Pod.", ["kubectl logs no tiene las opciones --lines ni --age, y api por sí solo se trataría como el nombre de un Pod.", "No existe un recurso get logs; los logs se leen con kubectl logs.", null, "describe muestra los detalles y eventos de un objeto, no los logs de los contenedores."]],
  "x29": ["Para un reporte rápido necesitas solo la dirección IP de cada Pod del namespace, en una sola línea. ¿Qué comando la imprime?", ["kubectl get pods -o wide --no-headers", "kubectl get pods -o jsonpath='{.status.podIP}'", "kubectl get pods --show-labels=podIP", "kubectl get pods -o jsonpath='{.items[*].status.podIP}'"], "Una lista se devuelve como un objeto con items, así que el jsonpath debe recorrer .items[*] para llegar a cada status.podIP. -o wide es tentador porque muestra las IP, pero también imprime otras columnas.", ["-o wide imprime muchas columnas, no solo las IP, así que igual tendrías que recortar la salida.", "Una respuesta de lista tiene un arreglo items; sin .items[*] esta ruta no encuentra nada.", "--show-labels es un booleano que agrega una columna de labels; no puede seleccionar el campo de la IP.", null]],
  "x30": ["El Pod app se cae al iniciar, y quieres una copia de él con el command del contenedor app reemplazado por una shell para poder explorarlo, sin cambiar el Pod original. ¿Qué comando usas?", ["kubectl exec -it app -c app -- sh", "kubectl edit pod app y cambiar el command", "kubectl debug app -it --copy-to=app-dbg --container=app -- sh", "kubectl debug app -it --image=busybox --target=app"], "kubectl debug --copy-to crea una copia del Pod, e indicar --container con un comando después de -- reemplaza el command de ese contenedor en la copia. La variante con --target es tentadora, pero se conecta al Pod original en lugar de crear una copia modificada.", ["exec necesita un contenedor en ejecución, y este se cae una y otra vez al iniciar.", "El command del contenedor de un Pod en ejecución no se puede editar, y además cambiaría el Pod original.", null, "Esto agrega un ephemeral container al Pod original que se cae; no crea una copia con un command cambiado."]],
  "x31": ["Un servicio implementa el protocolo estándar de health checking de gRPC en el puerto 9090. ¿Qué handler de liveness probe lo verifica de forma más directa?", ["httpGet en el puerto 9090 en la ruta /health", "grpc con port: 9090", "tcpSocket en el puerto 9090", "exec ejecutando curl localhost:9090"], "El handler de probe grpc llama al gRPC Health Checking Protocol en el puerto indicado y usa el estado de salud que reporta el propio servicio. tcpSocket es tentador porque funciona en cualquier puerto, pero solo prueba que algo está escuchando.", ["Los health checks de gRPC son llamadas gRPC, no solicitudes HTTP GET simples a una ruta.", null, "tcpSocket solo demuestra que el puerto acepta conexiones, no que el servicio se reporte como sano.", "curl envía HTTP, no el health check de gRPC; además necesita curl dentro de la imagen."]],
  "x32": ["Los Pods de un Deployment muestran brevemente Completed y luego CrashLoopBackOff. kubectl logs muestra la salida esperada y el código de salida es 0. ¿Cuál es la causa MÁS probable?", ["El proceso principal del contenedor termina y sale", "El límite de memoria es demasiado bajo", "El tag de la imagen no existe", "La readiness probe está fallando"], "Los Pods de un Deployment usan restartPolicy Always, así que un comando que se ejecuta y sale con 0 se reinicia una y otra vez, hasta entrar en backoff. Esa tarea corresponde a un Job, o el comando debe quedarse en primer plano. Una falla de readiness es tentadora, pero la readiness nunca reinicia contenedores.", [null, "Quedarse sin memoria da OOMKilled con el código de salida 137, no una salida limpia con 0.", "Una imagen inexistente causa ImagePullBackOff antes de que el contenedor llegue a ejecutarse o registrar algo.", "Una readiness probe que falla quita el Pod de los endpoints, pero nunca reinicia el contenedor."]],
  "x33": ["Necesitas encontrar qué Pod de un namespace se reinició más veces, enumerando los Pods ordenados por cantidad de reinicios. ¿Qué comando usas?", ["kubectl get pods --sort-by='.status.containerStatuses[0].restartCount'", "kubectl top pod --sort-by=restarts", "kubectl get pods -o wide --sort-by=RESTARTS", "kubectl get events --sort-by=restartCount"], "--sort-by recibe una expresión JSONPath, y restartCount está en el estado de cada contenedor. Usar el nombre de la columna RESTARTS es tentador porque aparece en la salida, pero las claves de ordenamiento deben ser rutas de campos.", [null, "kubectl top muestra el uso de CPU y memoria y solo ordena por esos valores; no tiene datos de reinicios.", "--sort-by recibe un campo JSONPath, no el encabezado de una columna.", "Los eventos no tienen un campo restartCount; describen lo que pasó, no contadores por Pod."]],
  "x34": ["El Pod A monta el ConfigMap app-cfg como un directorio completo; el Pod B monta una de sus keys con subPath. Después de actualizar el ConfigMap, solo el Pod A ve el nuevo valor. ¿Por qué?", ["El Pod B necesita una readiness probe para recargar el archivo", "Los volúmenes montados con subPath no reciben las actualizaciones del ConfigMap", "Las actualizaciones de un ConfigMap solo llegan al primer Pod que lo monta", "El Pod B debe establecer readOnly: false en el montaje"], "Los volúmenes ConfigMap se refrescan intercambiando un enlace simbólico, pero un montaje con subPath vincula directamente un archivo y nunca ve el intercambio, así que hay que reiniciar el contenedor. Culpar a readOnly es tentador, pero solo restringe las escrituras del contenedor.", ["Las probes no afectan cómo el kubelet refresca el contenido de los volúmenes.", null, "Todo Pod con un volumen ConfigMap normal recibe la actualización; la diferencia aquí es el subPath.", "Las actualizaciones las escribe el kubelet sin importar readOnly; readOnly solo limita al contenedor."]],
  "x35": ["Ya existe un ClusterRole pod-reader. El ServiceAccount ci del namespace dev debe recibir esos permisos solo dentro de dev. ¿Cuál es el MEJOR enfoque?", ["Un ClusterRoleBinding que haga referencia a pod-reader", "Copiar el ClusterRole en un Role con namespace en cada namespace", "Un RoleBinding en dev que haga referencia al ClusterRole pod-reader", "Agregar el namespace dev a la metadata del ClusterRole"], "Un RoleBinding puede hacer referencia a un ClusterRole y otorgar sus reglas solo en el namespace del RoleBinding. Copiar las reglas en un Role es tentador y funcionaría, pero reutilizar el ClusterRole es más sencillo y evita divergencias.", ["Un ClusterRoleBinding otorga los permisos en todos los namespaces, lo cual es más amplio de lo necesario.", "Funcionaría en dev, pero duplica reglas y aun así necesita un RoleBinding; un RoleBinding ya puede hacer referencia al ClusterRole.", null, "Los ClusterRoles tienen alcance de clúster y no tienen namespace; el alcance lo define el binding."]],
  "x36": ["Quieres ver todas las acciones que tus credenciales actuales tienen permitidas en el namespace dev. ¿Qué comando usas?", ["kubectl auth whoami -n dev", "kubectl get rolebindings -n dev -o wide", "kubectl describe clusterrole --mine", "kubectl auth can-i --list -n dev"], "kubectl auth can-i --list imprime los recursos y verbos permitidos para el usuario actual en el namespace. auth whoami es tentador porque está en el mismo grupo de comandos, pero solo informa la identidad.", ["whoami muestra con qué identidad estás autenticado, no lo que tienes permitido hacer.", "Esto enumera los bindings del namespace, pero aun así tendrías que resolver a mano cada rol y cada sujeto.", "No existe una opción --mine, y describir roles no muestra cuáles se aplican a ti.", null]],
  "x37": ["Un mutating admission webhook inyecta un sidecar de proxy, y un validating webhook rechaza los Pods cuyos contenedores no tienen límites de recursos. El sidecar inyectado no tiene límites. ¿Qué pasa con un Pod nuevo cuyo propio contenedor de app sí tiene límites?", ["Se admite, porque la validación se ejecuta antes que la mutación", "Se admite, porque los contenedores inyectados están exentos", "Se rechaza, porque la validación ve el Pod modificado", "El sidecar se quita para que el Pod pase"], "La admisión de mutación se ejecuta antes que la de validación, así que los validating webhooks evalúan el Pod después de agregar el sidecar, incluidos sus límites faltantes. Suponer que la validación va primero es el error tentador.", ["El orden es mutación y luego validación, así que la validación revisa el objeto final.", "Los validating webhooks ven el objeto modificado completo; los contenedores inyectados no están exentos de forma predeterminada.", null, "Los admission webhooks no deshacen los cambios de otros; el validating webhook solo puede admitir o rechazar."]],
  "x38": ["El namespace team-b tiene un LimitRange con `max.memory: 2Gi` para los contenedores. Se envía un Pod cuyo contenedor establece `limits.memory: 4Gi`. ¿Qué pasa?", ["Se rechaza en la admisión", "Se admite y se limita a 2Gi", "Se programa, pero termina por OOMKilled al llegar a 2Gi", "Se admite porque solo se aplica ResourceQuota"], "El plugin de admisión LimitRanger rechaza los contenedores cuyos requests o limits quedan fuera de min/max. Esperar que el valor se recorte es tentador porque LimitRange también establece valores predeterminados, pero solo completa los valores faltantes.", [null, "LimitRange no reduce los valores que superan max; rechaza el Pod.", "El Pod nunca se crea, así que no puede terminar por OOMKilled.", "LimitRange se aplica en la admisión igual que ResourceQuota."]],
  "x39": ["El namespace ops tiene una ResourceQuota con `pods: \"10\"`. El Deployment worker se escala de 8 a 12 réplicas. ¿Qué observas?", ["Se ejecutan 12 Pods y dos quedan marcados como Pending", "El comando de escalado se rechaza y siguen en ejecución 8 Pods", "Se eliminan los 12 Pods hasta que replicas se establezca en 10", "Se ejecutan 10 Pods y el ReplicaSet informa que se excedió la cuota"], "La cuota cuenta los Pods al crearlos, así que el ReplicaSet crea Pods hasta agotar la cuota y luego registra eventos forbidden: exceeded quota. Esperar Pods en Pending es tentador, pero los Pods rechazados nunca llegan a existir para quedar en Pending.", ["La cuota se verifica cuando se crean los Pods, así que los dos extra nunca llegan a crearse.", "Escalar solo cambia la spec del Deployment, que la cuota no bloquea; lo que falla es la creación de Pods.", "La cuota nunca elimina Pods en ejecución; solo rechaza los nuevos.", null]],
  "x40": ["Un nodo se está quedando sin memoria. Aloja un Pod sin requests ni limits, uno con requests menores que los limits y uno con requests iguales a los limits. ¿Cuál se desaloja primero?", ["El Pod con requests iguales a los limits", "El Pod sin requests ni limits", "El Pod con requests menores que los limits", "El Pod que inició más recientemente"], "Un Pod sin requests ni limits es BestEffort, y ante presión de memoria el kubelet desaloja esos Pods antes que los Burstable y Guaranteed. Burstable es tentador porque puede usar más de lo solicitado, pero BestEffort va primero.", ["Ese Pod tiene QoS Guaranteed y es el último en ser desalojado.", null, "Ese Pod es Burstable; se considera antes que los Pods Guaranteed, pero después de los BestEffort.", "La hora de inicio no es el criterio de desalojo; lo son la QoS y el uso en relación con los requests."]],
  "x41": ["La spec de un contenedor establece `cpu: \"0.25\"`. ¿Qué valor es equivalente?", ["25m", "250m", "0.25Mi", "2500m"], "Una CPU equivale a 1000m (milicores), así que 0.25 CPU es 250m. 25m es tentador si te equivocas con un decimal.", ["25m es 0.025 CPU, diez veces menos que 0.25.", null, "Mi es una unidad binaria de memoria y no es válida para CPU.", "2500m son 2.5 CPU, diez veces más que 0.25."]],
  "x42": ["El archivo app.env contiene tres líneas: LOG=debug, PORT=8080, MODE=dev. Quieres un ConfigMap con tres keys, una por línea. ¿Qué comando usas?", ["kubectl create configmap app --from-file=app.env", "kubectl create configmap app --from-literal=app.env", "kubectl create secret generic app --from-env-file=app.env", "kubectl create configmap app --from-env-file=app.env"], "--from-env-file interpreta cada línea KEY=value como su propia key. --from-file es tentador porque también lee un archivo, pero guarda todo el archivo bajo una sola key.", ["--from-file crea una key llamada app.env cuyo valor es el archivo completo.", "--from-literal espera pares key=value escritos en la línea de comandos, no el nombre de un archivo.", "Esto crea un Secret, no un ConfigMap, para configuraciones que no son sensibles.", null]],
  "x43": ["Los Pods fallan con ImagePullBackOff porque la imagen está en un registro privado que requiere inicio de sesión. ¿Cuál es la solución estándar?", ["Crear un Secret docker-registry e incluirlo en imagePullSecrets", "Crear un Secret generic con la contraseña y montarlo como volumen", "Establecer imagePullPolicy: Never", "Agregar la contraseña del registro como variable de entorno en el contenedor"], "Un Secret kubernetes.io/dockerconfigjson (kubectl create secret docker-registry) referenciado en imagePullSecrets del Pod o de su ServiceAccount permite que el kubelet se autentique. Montar las credenciales es tentador, pero las descargas ocurren antes de que se use cualquier volumen.", [null, "El kubelet no lee volúmenes montados para descargar imágenes; las credenciales deben referenciarse en imagePullSecrets.", "Eso impediría que el kubelet descargue la imagen en absoluto, así que el Pod falla a menos que la imagen ya esté en el nodo.", "Las variables de entorno se entregan al contenedor en ejecución; la imagen debe descargarse antes de que exista el contenedor."]],
  "x44": ["Tienes tls.crt y tls.key y necesitas un Secret llamado web-tls para un Ingress. ¿Qué comando usas?", ["kubectl create secret generic web-tls --cert=tls.crt --key=tls.key", "kubectl create configmap web-tls --from-file=tls.crt --from-file=tls.key", "kubectl create secret tls web-tls --cert=tls.crt --key=tls.key", "kubectl create certificate web-tls --cert=tls.crt --key=tls.key"], "kubectl create secret tls crea un Secret kubernetes.io/tls con las keys tls.crt y tls.key, que es lo que espera el Ingress. La variante generic es tentadora, pero no acepta esas opciones ni establece el tipo correcto.", ["generic no acepta --cert ni --key; necesitaría --from-file y no establecería el tipo tls.", "Una clave privada debe ir en un Secret, y la sección tls de un Ingress hace referencia a un Secret.", null, "kubectl no tiene un comando create certificate."]],
  "x45": ["Un script necesita un token de API de corta duración para el ServiceAccount build del namespace ci. ¿Qué comando emite uno?", ["kubectl get secret build-token -n ci", "kubectl describe sa build -n ci --token", "kubectl auth whoami --as=build -n ci", "kubectl create token build -n ci"], "kubectl create token usa la API TokenRequest para emitir un token con tiempo limitado para un ServiceAccount. Leer un Secret de token es tentador porque los clústeres antiguos los creaban automáticamente, pero ya no es el comportamiento predeterminado.", ["Los clústeres actuales no crean automáticamente Secrets de tokens de larga duración para los ServiceAccounts, así que este Secret normalmente no existe.", "describe no tiene una opción --token y no emite tokens.", "whoami solo informa la identidad; nunca emite credenciales.", null]],
  "x46": ["Un contenedor se ejecuta con el UID 1000 y no puede escribir en un volumen recién aprovisionado cuyo dueño es root. ¿Qué configuración del Pod suele resolver esto en los volúmenes que admiten cambios de propietario?", ["securityContext.runAsUser: 0", "allowPrivilegeEscalation: true", "securityContext.fsGroup: 1000", "readOnlyRootFilesystem: false"], "Con fsGroup establecido, los volúmenes compatibles pasan a pertenecer al grupo con ese GID y el grupo puede escribir en ellos, y los procesos del contenedor lo reciben como grupo suplementario. Ejecutar como root es tentador porque funciona, pero elimina un control de seguridad clave.", ["Ejecutar como root esquivaría el problema eliminando la protección de no ser root, lo que debilita la seguridad.", "Esto controla si un proceso puede obtener más privilegios que su padre; no cambia el propietario del volumen.", null, "Esto afecta el sistema de archivos raíz del contenedor, no los permisos de un volumen montado."]],
  "x47": ["Un Pod endurecido usa readOnlyRootFilesystem: true, pero la app se cae porque debe escribir archivos temporales en /tmp. ¿Cuál es la MEJOR solución?", ["Establecer readOnlyRootFilesystem: false", "Montar un emptyDir en /tmp", "Establecer runAsUser: 0 para que root pueda escribir", "Agregar la capability SYS_ADMIN"], "Un emptyDir en /tmp le da a la app un área temporal con escritura mientras el resto del sistema de archivos sigue siendo de solo lectura. Desactivar readOnlyRootFilesystem es tentador porque es rápido, pero elimina por completo el endurecimiento.", ["Funciona, pero renuncia a la protección de todo el sistema de archivos para resolver un problema en un solo directorio.", null, "Root tampoco puede escribir en un sistema de archivos de solo lectura, y ejecutar como root debilita la seguridad.", "SYS_ADMIN es muy amplia y no hace que un sistema de archivos raíz de solo lectura sea escribible para la app."]],
  "x48": ["El namespace dev tiene la label `pod-security.kubernetes.io/warn=restricted` y ninguna label enforce. Se crea un Pod que no cumple el perfil restricted. ¿Qué pasa?", ["El Pod se crea y el usuario ve una advertencia", "El Pod se rechaza", "El Pod se modifica para cumplir el perfil restricted", "El Pod se crea sin ninguna retroalimentación"], "Pod Security Admission tiene los modos enforce, audit y warn; warn solo devuelve advertencias al usuario. El rechazo es tentador, pero requiere la label enforce.", [null, "El rechazo ocurre solo en modo enforce; el modo warn deja pasar el Pod.", "Pod Security Admission nunca cambia los Pods; solo admite, advierte, audita o rechaza.", "El modo warn devuelve una advertencia al cliente, así que se le informa al usuario sobre las infracciones."]],
  "x49": ["Una NetworkPolicy sobre los Pods de backend tiene dos entradas `from` separadas: una con `namespaceSelector: {matchLabels: {team: web}}` y otra con `podSelector: {matchLabels: {role: fe}}`. ¿Quién puede conectarse?", ["Cualquier Pod de los namespaces team=web, o los Pods role=fe del namespace de la política", "Solo los Pods role=fe de los namespaces team=web", "Solo los Pods role=fe de cualquier namespace", "Todos los Pods de todos los namespaces"], "Los elementos separados de una lista from se combinan con OR, y un podSelector por sí solo aplica al namespace de la política. Leerlos como AND es el error tentador; eso solo ocurre cuando ambos selectores están en la misma entrada.", [null, "Eso sería una sola entrada con ambos selectores; las entradas separadas se combinan con OR.", "Un podSelector por sí solo coincide con los Pods del propio namespace de la política, no de todos los namespaces.", "Solo se permiten los Pods que coinciden con al menos una de las dos entradas."]],
  "x50": ["Una política debe permitir el ingress desde todos los Pods del namespace monitoring, que solo tiene las labels que Kubernetes agrega automáticamente. ¿Qué peer lo selecciona?", ["namespaceSelector que coincida con name: monitoring", "namespaceSelector que coincida con kubernetes.io/metadata.name: monitoring", "podSelector que coincida con namespace: monitoring", "ipBlock con el cidr del namespace monitoring"], "Kubernetes agrega la label inmutable kubernetes.io/metadata.name a cada namespace, así que se puede seleccionar sin agregar labels. Usar name: monitoring es tentador, pero esa label no existe a menos que alguien la establezca.", ["Una label name no se agrega automáticamente, así que este selector no coincide con nada a menos que alguien la agregue.", null, "podSelector coincide con labels de Pods del propio namespace de la política, no de otros namespaces.", "Los namespaces no tienen su propio CIDR, y las IP de los Pods cambian, así que ipBlock no está pensado para Pods dentro del clúster."]],
  "x51": ["Los Pods con la label app=api están seleccionados por dos NetworkPolicies: una permite el ingress desde app=web y la otra desde app=batch. ¿Qué tráfico llega a los Pods api?", ["Solo el tráfico de app=web, porque se creó primero", "Ningún tráfico, porque las políticas entran en conflicto", "El tráfico tanto de app=web como de app=batch", "Solo el tráfico que permiten ambas políticas a la vez"], "Las NetworkPolicies son aditivas: una vez que un Pod está seleccionado, el tráfico permitido es la unión de las reglas de todas las políticas. Tratarlas como una intersección es el error tentador porque suena más seguro.", ["El orden de creación no importa; las políticas no tienen prioridades.", "Las NetworkPolicies no entran en conflicto; solo agregan conexiones permitidas.", null, "Las políticas se combinan como una unión, no como una intersección."]],
  "x52": ["Los Pods pueden enviar tráfico de egress a 10.0.0.0/16, excepto a la subred de administración 10.0.5.0/24. ¿Cómo se escribe esto en una sola regla de egress?", ["Dos ipBlocks: permitir 10.0.0.0/16 y denegar 10.0.5.0/24", "namespaceSelector con cidr 10.0.0.0/16", "podSelector con except: 10.0.5.0/24", "ipBlock con cidr 10.0.0.0/16 y except [10.0.5.0/24]"], "ipBlock admite una lista except para excluir rangos del CIDR permitido. Un bloque de denegación separado es tentador, pero NetworkPolicy solo expresa permisos.", ["Las NetworkPolicies no tienen reglas de denegación; un segundo ipBlock solo puede permitir más tráfico.", "namespaceSelector selecciona namespaces por label y no tiene un campo cidr.", "podSelector coincide con labels y no tiene un campo except.", null]],
  "x53": ["Una regla de Ingress tiene `path: /login` con `pathType: Exact`. ¿Qué solicitud coincide?", ["/login/", "/login/reset", "/login", "/Login"], "pathType Exact compara la ruta de la URL de forma exacta y distinguiendo mayúsculas de minúsculas. /login/ es tentador porque Prefix lo aceptaría, pero Exact no.", ["La coincidencia Exact distingue mayúsculas de minúsculas y la barra final hace que sea una ruta distinta.", "Exact no coincide con subrutas; eso requeriría pathType Prefix.", null, "Las rutas se comparan distinguiendo mayúsculas de minúsculas, así que /Login es distinta de /login."]],
  "x54": ["Las solicitudes a un Ingress que no coincidan con ninguna de sus reglas de host o ruta deben ir al Service fallback en el puerto 80. ¿Qué campo del Ingress lo establece?", ["spec.defaultBackend", "spec.rules[].http.paths con la ruta /*", "spec.tls.defaultService", "metadata.annotations.default-backend"], "spec.defaultBackend maneja cualquier solicitud que no coincida con ninguna regla. Una ruta comodín es tentadora, pero con los tipos de ruta Prefix o Exact, /* es una ruta literal y no un comodín, y una regla de ruta no es el fallback estándar.", [null, "Las rutas estándar de Ingress no son globs; con Prefix o Exact, /* solo coincide con la ruta literal /*, así que no atrapa todo.", "La sección tls solo enumera hosts y Secrets de certificados; no tiene defaultService.", "Las annotations son extras específicos de cada controlador; el campo estándar es spec.defaultBackend."]],
  "x55": ["Un Ingress enruta el host shop.example.com, pero todavía no hay un registro DNS para él. ¿Cómo lo pruebas desde una shell que puede llegar a la IP del controlador?", ["curl shop.example.com --resolve-ingress", "kubectl port-forward ingress/shop 80:80", "curl <controller-ip>/shop.example.com", "curl -H 'Host: shop.example.com' <controller-ip>/"], "Los Ingress controllers eligen una regla según el header HTTP Host, así que establecerlo a mano te permite probar antes de que exista el DNS. Poner el host en la ruta de la URL es tentador, pero el controlador lo ve como una ruta, no como un host.", ["curl no tiene una opción --resolve-ingress, y sin DNS el nombre no se resolverá.", "port-forward funciona con Pods, Services y cargas de trabajo, no con objetos Ingress.", "Esto pone el host en la ruta; el Ingress compara el header Host, así que la regla no se usa.", null]],
  "x56": ["En un clúster local de kind, un Service de tipo LoadBalancer muestra EXTERNAL-IP <pending> indefinidamente. ¿Cuál es la razón MÁS probable?", ["El selector del Service no coincide con ningún Pod", "No existe ninguna implementación de load balancer en el clúster", "Los Services LoadBalancer necesitan una NetworkPolicy", "Los Pods no han pasado sus readiness probes"], "Los Services LoadBalancer dependen de un cloud controller o de un complemento como MetalLB para asignar direcciones; sin uno, la IP queda en pending. Es tentador culpar al selector, pero afecta los endpoints, no la asignación de direcciones.", ["Un selector incorrecto no da endpoints, pero no impide que se asigne una IP externa.", null, "Las NetworkPolicies filtran el tráfico; nunca se necesitan para asignar una dirección.", "La readiness afecta los endpoints, no si se aprovisiona el load balancer."]],
  "x57": ["Una app de carrito de compras guarda el estado de sesión en memoria, así que cada cliente debe seguir llegando al mismo Pod detrás de un Service ClusterIP. ¿Qué configuración lo proporciona?", ["externalTrafficPolicy: Local", "sessionAffinity: ClientIP", "clusterIP: None", "publishNotReadyAddresses: true"], "sessionAffinity: ClientIP envía las solicitudes de una misma IP de cliente al mismo Pod. externalTrafficPolicy: Local es tentador porque también mantiene el tráfico local, pero se refiere a los nodos, no a una asignación de cliente a Pod.", ["Esto mantiene el tráfico externo en los Pods del nodo que lo recibe; no fija un cliente a un Pod.", null, "Un Service headless elimina la IP virtual y el balanceo de carga en lugar de agregar persistencia de sesión.", "Esto solo publica los Pods que no están Ready; no tiene nada que ver con la persistencia de sesión."]],
  "x58": ["¿Qué comando crea un Service NodePort llamado web con el puerto 80 reenviando al target port 8080?", ["kubectl create service web --type=NodePort --port=80:8080", "kubectl expose service web --node-port=8080", "kubectl port-forward service/web 80:8080 --nodeport", "kubectl create service nodeport web --tcp=80:8080"], "kubectl create service nodeport <name> --tcp=<port>:<targetPort> crea el Service con el selector app=<name>. La variante con --type es tentadora porque expose usa --type, pero create service usa un subcomando.", ["kubectl create service necesita un subcomando de tipo como nodeport; no tiene una opción --type.", "expose crea un Service a partir de un recurso existente y no tiene una opción --node-port.", "port-forward crea un túnel local; nunca crea un Service.", null]],
  "x59": ["El Service db tiene `port: 80` y `targetPort: 5432`. Los Pods de la app tienen una política default-deny de egress y necesitan una regla que permita el tráfico hacia los Pods de db. ¿Qué puerto debe permitir la regla de egress?", ["5432, el puerto del Pod", "80, el puerto del Service", "Deben enumerarse tanto el 80 como el 5432", "Ningún puerto, porque los Services omiten las NetworkPolicies"], "El tráfico de un Service se traduce a la IP y al targetPort de un Pod antes de verificar las reglas de NetworkPolicy, así que la regla debe permitir el 5432 (y DNS si se usan nombres). Permitir el puerto 80 del Service es el error tentador.", [null, "Las NetworkPolicies se aplican sobre las IP y los puertos de los Pods después de traducir la dirección del Service, así que el paquete no usa el 80.", "Enumerar el 80 no agrega nada; solo se verifica el puerto del Pod de destino.", "El tráfico de un Service sigue sujeto a las NetworkPolicies una vez que se traduce a direcciones de Pods."]],
  "x60": ["En el clúster se ejecutan dos Ingress controllers, y un Ingress nuevo debe ser manejado solo por el que tiene la IngressClass llamada nginx. ¿Qué campo lo establece?", ["metadata.labels.controller: nginx", "spec.defaultBackend.class: nginx", "spec.ingressClassName: nginx", "spec.rules[].host: nginx"], "spec.ingressClassName nombra la IngressClass, y solo el controlador detrás de ella maneja el Ingress. Usar una label es tentador porque las labels seleccionan muchas cosas, pero los controladores usan la IngressClass.", ["Los controladores no eligen Ingresses por una label arbitraria.", "defaultBackend apunta a un Service o recurso y no tiene un campo class.", null, "host es el nombre de host que usan los clientes, no el controlador que maneja el Ingress."]],
});
